(** * 1RB0RB_0LC1RA_1RD1LC_1LA1LE_1LF0LD_---0LA halts

    Cells are read in pairs: a = 11, b = 01.  A record configuration is
      0^inf  W  0 1  1 B> 0^inf        with W a word over {a, b},
    and one sweep acts on W as a three-state right-to-left letter transducer; at the
    left edge the word grows, the machine halts, or the whole tape is rewritten (a
    level ends).  A level whose word starts with a long run b^(12q+12+r) behaves like
    the short word obtained by cutting the run down to b^r, delayed by a factor 4^(q+1).

    The file follows the machine through 25 levels.  The run lengths are towers of
    powers of 4 and are never computed: each level is evaluated on a word whose long
    runs have symbolic lengths, and only residues of the lengths modulo powers of 3
    are carried from one level to the next.  The reduced word of level 25 halts.

    Layout (one module per layer):
      Sim356, Blocks356, Ovf356   the transducer, the sweeps, the end of a level
      Tail356, Level356           the long run as a periodic emitter; the level reduction
      Test356, Level1_356         the first level, by direct computation
      Sym356, Step356             words with symbolic run lengths, their evaluator, one level as a step
      Lev2_356 ... Lev25_356      the reduced word of each level (generated)
      Resid356                    4^x modulo powers of 3
      Reach356                    the chain of levels (generated)
    The final theorem is [halt] at the end of the file.

    AI assistance: this proof, the scripts and the checks were produced with the help of Claude (Anthropic). *)

From BusyCoq Require Import Individual62.
Require Import String.
Require Lia PeanoNat ZArith Znumtheory Zpow_facts.
From Coq Require Lists.List.

Definition tm : TM := TM_from_str "1RB0RB_0LC1RA_1RD1LC_1LA1LE_1LF0LD_---0LA".

Module Sim356.

(** * 1RB0RB_0LC1RA_1RD1LC_1LA1LE_1LF0LD_---0LA: the machine as a letter transducer (layer 0)

    Cells are read in pairs: a = 11, b = 01, c = 10.  A record configuration is
      0^inf  W  0 1  1 B> 0^inf        with W a word over {a, b}.
    One "sweep" (a left-moving pass in states D/E/F/C and the right-moving pass in
    states A/B back to the next record) acts on W as a three-state right-to-left
    letter transducer; reaching the left edge either grows the word, halts the
    machine, or rewrites the whole tape by a right-moving pass shifted by one cell.

    Main statements: [sim] (one sweep), [run_spec] and [run_halts] (iteration),
    [sweep_act] (the sweep is the transducer [act]).

    AI assistance: this proof, the scripts and the checks were produced with the help of Claude (Anthropic). *)

Import Lia PeanoNat String.
Import Coq.Lists.List.
Open Scope list_scope.
Import ListNotations.


Notation "c -->* c'" := (c -[ tm ]->* c') (at level 40).
Notation "c -->+ c'" := (c -[ tm ]->+ c') (at level 40).

(** ** Letters and encodings *)

Inductive L2 := La | Lb.
Inductive P3 := Pa | Pb | Pc.

Definition lcL (x : L2) : Sym := match x with La => 1 | Lb => 0 end.

(** Left side of the tape: the head of the list is the rightmost pair. *)
Fixpoint encL (w : list L2) : side :=
  match w with
  | [] => const 0
  | x :: w' => encL w' << lcL x << 1
  end.

Definition lcP (x : P3) : Sym := match x with Pa => 1 | Pb => 0 | Pc => 1 end.
Definition rcP (x : P3) : Sym := match x with Pa => 1 | Pb => 1 | Pc => 0 end.

(** Right side of the tape: the head of the list is the leftmost pair. *)
Fixpoint encR (v : list P3) (r : side) : side :=
  match v with
  | [] => r
  | x :: v' => lcP x >> rcP x >> encR v' r
  end.

(** Record configuration.  In a record the list starts with [Lb]. *)
Definition rec (U : list L2) : Q * tape := encL U << 1 {{B}}> const 0.

(** ** Cell-level rules *)

Lemma D_a l r : l << 1 << 1 <{{D}} r -->* l <{{D}} 0 >> 1 >> r.
Proof. execute. Qed.

Lemma D_ab l r : l << 1 << 1 << 0 << 1 <{{D}} r -->* l << 0 << 1 << 0 << 1 {{A}}> r.
Proof. execute. Qed.

Lemma D_bb l r : l << 0 << 1 << 0 << 1 <{{D}} r -->* l <{{C}} 1 >> 0 >> 1 >> 1 >> r.
Proof. execute. Qed.

Lemma C_a l r : l << 1 << 1 <{{C}} r -->* l <{{C}} 1 >> 1 >> r.
Proof. execute. Qed.

Lemma C_b l r : l << 0 << 1 <{{C}} r -->* l <{{D}} 0 >> 1 >> r.
Proof. execute. Qed.

Lemma D_grow r : const 0 <{{D}} r -->* const 0 << 1 << 1 {{A}}> r.
Proof. execute. Qed.

Lemma D_halt r : halts tm (const 0 << 0 << 1 <{{D}} r).
Proof.
  eapply halts_evstep with (c' := const 0 <{{F}} 1 >> 1 >> r).
  - apply halted_halts. reflexivity.
  - execute.
Qed.

Lemma C_edge r : const 0 <{{C}} 1 >> r -->* const 0 << 1 << 1 {{A}}> 0 >> 1 >> r.
Proof. execute. Qed.

Lemma A_b l r : l {{A}}> 0 >> 1 >> r -->* l << 1 << 1 {{A}}> r.
Proof. execute. Qed.

Lemma A_a l r : l {{A}}> 1 >> 1 >> r -->* l << 0 << 1 {{A}}> r.
Proof. execute. Qed.

Lemma A_c l r : l {{A}}> 1 >> 0 >> r -->* l << 0 << 1 {{A}}> r.
Proof. execute. Qed.

Lemma A_end l : l {{A}}> const 0 -->+ l << 1 {{B}}> const 0.
Proof. execute. Qed.

Lemma A_end0 l : l {{A}}> 0 >> const 0 -->+ l << 1 {{B}}> const 0.
Proof. execute. Qed.

Lemma B_start l : l << 0 << 1 << 1 {{B}}> const 0 -->* l <{{D}} 0 >> 1 >> 1 >> 0 >> const 0.
Proof. execute. Qed.

(** ** The left-moving pass *)

Inductive St := T0 | T1 | T2.

Inductive DOut :=
| DTurn (w : list L2) (v : list P3)
| DHalt
| DOvf (v : list P3).

Fixpoint dscan (s : St) (w : list L2) (v : list P3) {struct w} : DOut :=
  match w with
  | [] => match s with
          | T0 => DTurn [La] v
          | T1 => DHalt
          | T2 => DOvf v
          end
  | La :: w' => match s with
                | T0 => dscan T0 w' (Pb :: v)
                | T1 => DTurn (Lb :: Lb :: w') v
                | T2 => dscan T2 w' (Pa :: v)
                end
  | Lb :: w' => match s with
                | T0 => dscan T1 w' v
                | T1 => dscan T2 w' (Pc :: Pa :: v)
                | T2 => dscan T0 w' (Pb :: v)
                end
  end.

Definition dconf (s : St) (w : list L2) (v : list P3) (r : side) : Q * tape :=
  match s with
  | T0 => encL w <{{D}} encR v r
  | T1 => encL (Lb :: w) <{{D}} encR v r
  | T2 => encL w <{{C}} encR v r
  end.

Definition DGood (c : Q * tape) (o : DOut) (r : side) : Prop :=
  match o with
  | DTurn w v => c -->* encL w {{A}}> encR v r
  | DHalt => halts tm c
  | DOvf v => c -->* const 0 <{{C}} encR v r
  end.

Lemma DGood_step c c' o r : c -->* c' -> DGood c' o r -> DGood c o r.
Proof.
  intros H; destruct o; cbn; intros H'.
  - eapply evstep_trans; eassumption.
  - eapply halts_evstep; eassumption.
  - eapply evstep_trans; eassumption.
Qed.

Lemma dscan_spec w : forall s v r, DGood (dconf s w v r) (dscan s w v) r.
Proof.
  induction w as [|x w IH]; intros s v r.
  - destruct s; cbn.
    + apply D_grow.
    + apply D_halt.
    + apply evstep_refl.
  - destruct x, s; cbn [dscan].
    + eapply DGood_step; [ | apply (IH T0 (Pb :: v) r) ]. apply D_a.
    + cbn. apply D_ab.
    + eapply DGood_step; [ | apply (IH T2 (Pa :: v) r) ]. apply C_a.
    + apply (IH T1 v r).
    + eapply DGood_step; [ | apply (IH T2 (Pc :: Pa :: v) r) ]. apply D_bb.
    + eapply DGood_step; [ | apply (IH T0 (Pb :: v) r) ]. apply C_b.
Qed.

(** ** The right-moving pass *)

Definition sig (x : P3) : L2 := match x with Pa => Lb | Pb => La | Pc => Lb end.

Lemma apass v : forall w r, encL w {{A}}> encR v r -->* encL (rev_append (map sig v) w) {{A}}> r.
Proof.
  induction v as [|x v IH]; intros w r.
  - apply evstep_refl.
  - cbn [map rev_append].
    eapply evstep_trans; [ | apply IH ].
    destruct x; cbn.
    + apply A_a.
    + apply A_b.
    + apply A_c.
Qed.

(** The shifted right-moving pass at a level end. *)

Definition aletter (c1 c2 : Sym) : option L2 :=
  match c1, c2 with
  | 0, 1 => Some La
  | 1, 1 => Some Lb
  | 1, 0 => Some Lb
  | 0, 0 => None
  end.

Fixpoint oscan (carry : Sym) (v : list P3) (acc : list L2) : option (list L2) :=
  match v with
  | [] => match carry with 0 => Some acc | 1 => None end
  | x :: v' => match aletter carry (lcP x) with
               | Some y => oscan (rcP x) v' (y :: acc)
               | None => None
               end
  end.

Lemma oscan_spec v : forall carry acc U, oscan carry v acc = Some U ->
  encL acc {{A}}> carry >> encR v (const 0) -->+ rec U.
Proof.
  induction v as [|x v IH]; intros carry acc U H.
  - destruct carry; cbn in H; inversion H; subst. apply A_end0.
  - cbn [oscan] in H.
    destruct (aletter carry (lcP x)) as [y|] eqn:E; [ | discriminate ].
    eapply evstep_progress_trans; [ | apply (IH _ _ _ H) ].
    destruct carry, x; cbn in E; inversion E; subst; cbn.
    + apply A_b.
    + apply A_b.
    + apply A_a.
    + apply A_c.
    + apply A_a.
Qed.

(** ** One sweep *)

Inductive Out := Next (U : list L2) | Halt | Stuck.

Definition ovf (v : list P3) : Out :=
  match v with
  | x :: _ => match lcP x with
              | 1 => match oscan 0 v [La] with Some U => Next U | None => Stuck end
              | 0 => Stuck
              end
  | [] => Stuck
  end.

Definition sweep (U : list L2) : Out :=
  match U with
  | Lb :: W =>
    match dscan T0 W [Pb; Pc] with
    | DTurn w v => Next (rev_append (map sig v) w)
    | DHalt => Halt
    | DOvf v => ovf v
    end
  | _ => Stuck
  end.

Definition Good (c : Q * tape) (o : Out) : Prop :=
  match o with
  | Next U => c -->+ rec U
  | Halt => halts tm c
  | Stuck => True
  end.

Theorem sim U : Good (rec U) (sweep U).
Proof.
  destruct U as [|x W]; [ exact I | ].
  destruct x; [ exact I | ].
  unfold sweep.
  pose proof (dscan_spec W T0 [Pb; Pc] (const 0)) as H.
  assert (H0 : rec (Lb :: W) -->* dconf T0 W [Pb; Pc] (const 0)) by apply B_start.
  destruct (dscan T0 W [Pb; Pc]) as [w v| |v]; cbn [DGood] in H.
  - cbn [Good].
    eapply evstep_progress_trans; [ apply H0 | ].
    eapply evstep_progress_trans; [ apply H | ].
    eapply evstep_progress_trans; [ apply apass | ].
    apply A_end.
  - cbn [Good]. eapply halts_evstep; eassumption.
  - unfold ovf. destruct v as [|x v]; [ exact I | ].
    destruct (lcP x) eqn:E; [ exact I | ].
    destruct (oscan 0 (x :: v) [La]) as [U|] eqn:E2; [ | exact I ].
    cbn [Good].
    eapply evstep_progress_trans; [ apply H0 | ].
    eapply evstep_progress_trans; [ apply H | ].
    eapply evstep_progress_trans; [ | apply (oscan_spec _ _ _ _ E2) ].
    cbn [encR]. rewrite E. apply C_edge.
Qed.

(** ** Iteration *)

Fixpoint run (n : nat) (U : list L2) : Out :=
  match n with
  | O => Next U
  | S n' => match sweep U with
            | Next U' => run n' U'
            | o => o
            end
  end.

Definition Good' (c : Q * tape) (o : Out) : Prop :=
  match o with
  | Next U => c -->* rec U
  | Halt => halts tm c
  | Stuck => True
  end.

Theorem run_spec n : forall U, Good' (rec U) (run n U).
Proof.
  induction n as [|n IH]; intros U; cbn [run].
  - apply evstep_refl.
  - pose proof (sim U) as H.
    destruct (sweep U) as [U'| |]; cbn [Good] in H.
    + specialize (IH U'). destruct (run n U'); cbn [Good'] in *.
      * eapply evstep_trans; [ apply progress_evstep; apply H | apply IH ].
      * eapply halts_evstep; [ apply IH | apply progress_evstep; apply H ].
      * exact I.
    + exact H.
    + exact I.
Qed.

Theorem run_halts U0 n : c0 -->* rec U0 -> run n U0 = Halt -> halts tm c0.
Proof.
  intros H E. pose proof (run_spec n U0) as H1. rewrite E in H1.
  eapply halts_evstep; eassumption.
Qed.

Theorem run_reach U0 n U : c0 -->* rec U0 -> run n U0 = Next U -> c0 -->* rec U.
Proof.
  intros H E. pose proof (run_spec n U0) as H1. rewrite E in H1.
  eapply evstep_trans; eassumption.
Qed.

(** ** The start: the first record, after 31 steps, is  1111 0 1 0 1 1 B>. *)

Definition U0 : list L2 := [Lb; Lb; La; La].

Lemma init : c0 -->* rec U0.
Proof. unfold rec, U0. cbn [encL lcL]. solve_init. Qed.

(** ** The sweep as a three-state right-to-left transducer *)

Inductive Ex := EI | E0 | E1 | E2.

Fixpoint act (s : St) (w : list L2) {struct w} : list L2 * Ex :=
  match w with
  | [] => ([], match s with T0 => E0 | T1 => E1 | T2 => E2 end)
  | La :: w' => match s with
                | T0 => let (u, e) := act T0 w' in (La :: u, e)
                | T1 => (Lb :: w', EI)
                | T2 => let (u, e) := act T2 w' in (Lb :: u, e)
                end
  | Lb :: w' => match s with
                | T0 => let (u, e) := act T1 w' in (Lb :: u, e)
                | T1 => let (u, e) := act T2 w' in (Lb :: u, e)
                | T2 => let (u, e) := act T0 w' in (La :: u, e)
                end
  end.

Definition grow (p : list L2 * Ex) : list L2 :=
  match snd p with E0 => fst p ++ [La] | _ => fst p end.

Definition pre (s : St) : list L2 := match s with T1 => [Lb] | _ => [] end.

Lemma dscan_act w : forall s v,
  match dscan s w v with
  | DTurn w' v' => rev_append (map sig v') w' = rev_append (map sig v) (pre s ++ grow (act s w))
                   /\ (snd (act s w) = EI \/ snd (act s w) = E0)
  | DHalt => snd (act s w) = E1
  | DOvf _ => snd (act s w) = E2
  end.
Proof.
  induction w as [|x w IH]; intros s v.
  - destruct s; cbn; auto.
  - destruct x, s; cbn [dscan act].
    + specialize (IH T0 (Pb :: v)). destruct (dscan T0 w (Pb :: v));
        destruct (act T0 w) as [u e]; destruct e; cbn in *; intuition congruence.
    + cbn. auto.
    + specialize (IH T2 (Pa :: v)). destruct (dscan T2 w (Pa :: v));
        destruct (act T2 w) as [u e]; destruct e; cbn in *; intuition congruence.
    + specialize (IH T1 v). destruct (dscan T1 w v);
        destruct (act T1 w) as [u e]; destruct e; cbn in *; intuition congruence.
    + specialize (IH T2 (Pc :: Pa :: v)). destruct (dscan T2 w (Pc :: Pa :: v));
        destruct (act T2 w) as [u e]; destruct e; cbn in *; intuition congruence.
    + specialize (IH T0 (Pb :: v)). destruct (dscan T0 w (Pb :: v));
        destruct (act T0 w) as [u e]; destruct e; cbn in *; intuition congruence.
Qed.

(** One sweep, stated with the transducer: inside the word nothing else happens;
    at the left edge the word grows (exit in T0), the machine halts (T1), or the
    level ends (T2). *)
Definition sweep' (U : list L2) : Out :=
  match U with
  | Lb :: W =>
    match act T0 W with
    | (u, EI) => Next (Lb :: La :: u)
    | (u, E0) => Next (Lb :: La :: u ++ [La])
    | (_, E1) => Halt
    | (_, E2) => match dscan T0 W [Pb; Pc] with DOvf v => ovf v | _ => Stuck end
    end
  | _ => Stuck
  end.

Lemma sweep_act U : sweep U = sweep' U.
Proof.
  destruct U as [|x W]; [ reflexivity | ]. destruct x; [ reflexivity | ].
  unfold sweep, sweep'.
  pose proof (dscan_act W T0 [Pb; Pc]) as H.
  destruct (dscan T0 W [Pb; Pc]); destruct (act T0 W) as [u e]; destruct e; cbn in *;
    intuition (try congruence).
Qed.

End Sim356.

Module Test356.

