Lemma run_B518 : run 519 U_A6 = Next U_B518.
Proof. vm_compute. reflexivity. Qed.

Lemma reach_A6 : c0 -->* rec U_A6.
Proof. exact (run_reach _ _ _ init run_A6). Qed.

Lemma reach_B518 : c0 -->* rec U_B518.
Proof. eapply evstep_trans; [ apply reach_A6 | ]. pose proof (run_spec 519 U_A6) as H. rewrite run_B518 in H. exact H. Qed.

