Module Blocks356.

(** * 1RB0RB_0LC1RA_1RD1LC_1LA1LE_1LF0LD_---0LA: blocks, emitters and cascades (layer 1a)

    A suffix of the zone evolves on its own (information only flows right to left)
    and now and then passes a state to what is left of it.

    AI assistance: this proof, the scripts and the checks were produced with the help of Claude (Anthropic). *)

Import Sim356.
Import Lia PeanoNat.
Import Coq.Lists.List.
Import ListNotations.
Open Scope list_scope.

(** ** Scanning a block *)

Fixpoint actp (s : St) (u : list L2) {struct u} : list L2 * option St :=
  match u with
  | [] => ([], Some s)
  | La :: u' => match s with
                | T0 => let (v, o) := actp T0 u' in (La :: v, o)
                | T1 => (Lb :: u', None)
                | T2 => let (v, o) := actp T2 u' in (Lb :: v, o)
                end
  | Lb :: u' => match s with
                | T0 => let (v, o) := actp T1 u' in (Lb :: v, o)
                | T1 => let (v, o) := actp T2 u' in (Lb :: v, o)
                | T2 => let (v, o) := actp T0 u' in (La :: v, o)
                end
  end.

Lemma actp_app u : forall s x,
  actp s (u ++ x) = match actp s u with
                    | (u', Some s') => let (x', o) := actp s' x in (u' ++ x', o)
                    | (u', None) => (u' ++ x, None)
                    end.
Proof.
  induction u as [|a u IH]; intros s x.
  - cbn. destruct (actp s x); reflexivity.
  - destruct a, s; cbn [actp app]; try reflexivity;
      rewrite IH; destruct (actp _ u) as [u' [s'|]]; try destruct (actp s' x); reflexivity.
Qed.

Definition ex_of (o : option St) : Ex :=
  match o with None => EI | Some T0 => E0 | Some T1 => E1 | Some T2 => E2 end.

Lemma act_actp w : forall s, act s w = (fst (actp s w), ex_of (snd (actp s w))).
Proof.
  induction w as [|a w IH]; intros s.
  - destruct s; reflexivity.
  - destruct a, s; cbn [act actp]; try reflexivity;
      rewrite IH; destruct (actp _ w); reflexivity.
Qed.

(** ** Records with an explicit block *)

Definition UU (n : nat) (Z : list L2) : list L2 := Lb :: repeat La n ++ Lb :: Z.

Lemma act_T0_block n Z :
  act T0 (repeat La n ++ Lb :: Z) = (repeat La n ++ Lb :: fst (act T1 Z), snd (act T1 Z)).
Proof.
  induction n as [|n IH]; cbn [repeat app act].
  - destruct (act T1 Z); reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma sweep_quiet n Z Z' : actp T1 Z = (Z', None) -> sweep (UU n Z) = Next (UU (S n) Z').
Proof.
  intros H. rewrite sweep_act. unfold UU, sweep'.
  rewrite act_T0_block, act_actp, H. reflexivity.
Qed.

Lemma sweep_grow n Z Z' : actp T1 Z = (Z', Some T0) -> sweep (UU n Z) = Next (UU (S n) (Z' ++ [La])).
Proof.
  intros H. rewrite sweep_act. unfold UU, sweep'.
  rewrite act_T0_block, act_actp, H. cbn [fst snd ex_of repeat app].
  rewrite <- app_assoc. reflexivity.
Qed.

Lemma sweep_halt n Z Z' : actp T1 Z = (Z', Some T1) -> sweep (UU n Z) = Halt.
Proof.
  intros H. rewrite sweep_act. unfold UU, sweep'.
  rewrite act_T0_block, act_actp, H. reflexivity.
Qed.

(** ** Quiet runs and emissions *)

Fixpoint qf (m : nat) (u : list L2) : option (list L2) :=
  match m with
  | O => Some u
  | S m' => match actp T1 u with
            | (u1, None) => qf m' u1
            | _ => None
            end
  end.

Definition em1 (u : list L2) : option (St * list L2) :=
  match actp T1 u with
  | (u1, Some s) => Some (s, u1)
  | _ => None
  end.

Definition emf (m : nat) (u : list L2) : option (St * list L2) :=
  match m with
  | O => None
  | S m' => match qf m' u with Some u1 => em1 u1 | None => None end
  end.

Lemma qf_add m1 : forall m2 u u1, qf m1 u = Some u1 -> qf (m1 + m2) u = qf m2 u1.
Proof.
  induction m1 as [|m1 IH]; intros m2 u u1 H; cbn [qf Nat.add] in *.
  - inversion H. reflexivity.
  - destruct (actp T1 u) as [u0 [s|]]; [ discriminate | ]. apply IH. exact H.
Qed.

Lemma emf_qf m1 m2 u u1 : qf m1 u = Some u1 -> emf (m1 + S m2) u = emf (S m2) u1.
Proof.
  intros H. rewrite Nat.add_succ_r. cbn [emf]. rewrite (qf_add _ m2 _ _ H). reflexivity.
Qed.

Lemma qf_app m : forall u u' v, qf m u = Some u' -> qf m (u ++ v) = Some (u' ++ v).
Proof.
  induction m as [|m IH]; intros u u' v H; cbn [qf] in *.
  - inversion H. reflexivity.
  - rewrite actp_app. destruct (actp T1 u) as [u0 [s|]]; [ discriminate | ]. apply IH. exact H.
Qed.

Lemma run_quiet m : forall n Z Z', qf m Z = Some Z' -> run m (UU n Z) = Next (UU (m + n) Z').
Proof.
  induction m as [|m IH]; intros n Z Z' H; cbn [qf run] in *.
  - inversion H. reflexivity.
  - destruct (actp T1 Z) as [Z1 [s|]] eqn:E; [ discriminate | ].
    rewrite (sweep_quiet _ _ _ E). rewrite (IH _ _ _ H). rewrite Nat.add_succ_r. reflexivity.
Qed.

(** Cascade: an emitter [u] with a block [v] to its left. *)

Lemma emf_then_quiet m u s u1 v v1 :
  emf m u = Some (s, u1) -> actp s v = (v1, None) -> qf m (u ++ v) = Some (u1 ++ v1).
Proof.
  destruct m as [|m]; [ discriminate | ]. cbn [emf]. intros H Hv.
  destruct (qf m u) as [u0|] eqn:E; [ | discriminate ].
  unfold em1 in H. destruct (actp T1 u0) as [u2 [t|]] eqn:E1; [ | discriminate ].
  inversion H; subst.
  rewrite <- Nat.add_1_r. rewrite (qf_add _ 1 _ _ (qf_app _ _ _ v E)).
  cbn [qf]. rewrite actp_app, E1, Hv. reflexivity.
Qed.

Lemma emf_then_emit m u s u1 v v1 t :
  emf m u = Some (s, u1) -> actp s v = (v1, Some t) -> emf m (u ++ v) = Some (t, u1 ++ v1).
Proof.
  destruct m as [|m]; [ discriminate | ]. cbn [emf]. intros H Hv.
  destruct (qf m u) as [u0|] eqn:E; [ | discriminate ].
  unfold em1 in H. destruct (actp T1 u0) as [u2 [t'|]] eqn:E1; [ | discriminate ].
  inversion H; subst.
  rewrite (qf_app _ _ _ v E). unfold em1. rewrite actp_app, E1, Hv. reflexivity.
Qed.

(** [Feed u v M u' v']: during [M] sweeps the emitter [u] emits states that all stop
    inside [v]; the last of the [M] sweeps is an emission (or [M = 0]). *)
Inductive Feed : list L2 -> list L2 -> nat -> list L2 -> list L2 -> Prop :=
| Feed0 u v : Feed u v 0 u v
| FeedS u v m s u1 v1 M u' v' :
    emf m u = Some (s, u1) -> actp s v = (v1, None) -> Feed u1 v1 M u' v' ->
    Feed u v (m + M) u' v'.

Lemma Feed_quiet u v M u' v' : Feed u v M u' v' -> qf M (u ++ v) = Some (u' ++ v').
Proof.
  induction 1 as [|u v m s u1 v1 M u' v' H1 H2 _ IH].
  - reflexivity.
  - rewrite (qf_add _ M _ _ (emf_then_quiet _ _ _ _ _ _ H1 H2)). exact IH.
Qed.

Lemma Feed_em u v M u1 v1 m s u2 v2 t :
  Feed u v M u1 v1 -> emf m u1 = Some (s, u2) -> actp s v1 = (v2, Some t) ->
  emf (M + m) (u ++ v) = Some (t, u2 ++ v2).
Proof.
  intros HF H1 H2. destruct m as [|m]; [ discriminate | ].
  rewrite (emf_qf _ m _ _ (Feed_quiet _ _ _ _ _ HF)).
  eapply emf_then_emit; eassumption.
Qed.

Lemma Feed_trans u v M1 u1 v1 M2 u2 v2 :
  Feed u v M1 u1 v1 -> Feed u1 v1 M2 u2 v2 -> Feed u v (M1 + M2) u2 v2.
Proof.
  induction 1 as [|u v m s u1 v1 M u' v' H1 H2 _ IH]; intros HF.
  - exact HF.
  - rewrite <- Nat.add_assoc. eapply FeedS; eauto.
Qed.

End Blocks356.

Module Ovf356.

(** * 1RB0RB_0LC1RA_1RD1LC_1LA1LE_1LF0LD_---0LA: the level end as a letter map (layer 0b)

    When the scan reaches the left edge in state T2, the tape is rewritten by a
    right-moving pass shifted by one cell.  [oim] computes the result letter by letter.

    AI assistance: this proof, the scripts and the checks were produced with the help of Claude (Anthropic). *)

Import Sim356 Blocks356.
Import Lia PeanoNat.
Import Coq.Lists.List.
Import ListNotations.
Open Scope list_scope.

(** One letter of the left-moving pass when no turn happens: the pair it leaves
    behind and the next state. *)
Definition dstep (s : St) (x : L2) : option (P3 * St) :=
  match s, x with
  | T0, La => Some (Pb, T0)
  | T0, Lb => Some (Pa, T1)
  | T1, La => None
  | T1, Lb => Some (Pc, T2)
  | T2, La => Some (Pa, T2)
  | T2, Lb => Some (Pb, T0)
  end.

(** Images with the list of pairs left behind (for the link with [dscan]). *)
Fixpoint oimg (s : St) (w : list L2) {struct w} : option (Sym * list L2 * list P3) :=
  match w with
  | [] => match s with T2 => Some (0, [], []) | _ => None end
  | x :: w' =>
    match dstep s x with
    | None => None
    | Some (d, s') =>
      match oimg s' w' with
      | None => None
      | Some (c', I', D') =>
        match aletter c' (lcP d) with
        | Some y => Some (rcP d, y :: I', d :: D')
        | None => None
        end
      end
    end
  end.

(** The same without the pairs. *)
Fixpoint oim (s : St) (w : list L2) {struct w} : option (Sym * list L2) :=
  match w with
  | [] => match s with T2 => Some (0, []) | _ => None end
  | x :: w' =>
    match dstep s x with
    | None => None
    | Some (d, s') =>
      match oim s' w' with
      | None => None
      | Some (c', I') =>
        match aletter c' (lcP d) with
        | Some y => Some (rcP d, y :: I')
        | None => None
        end
      end
    end
  end.

Lemma oim_oimg w : forall s c I, oim s w = Some (c, I) -> exists D, oimg s w = Some (c, I, D).
Proof.
  induction w as [|x w IH]; intros s c I H; cbn [oim oimg] in *.
  - destruct s; try discriminate. inversion H; subst. eexists; reflexivity.
  - destruct (dstep s x) as [[d s']|]; [ | discriminate ].
    destruct (oim s' w) as [[c' I']|] eqn:E; [ | discriminate ].
    destruct (IH _ _ _ E) as [D' HD]. rewrite HD.
    destruct (aletter c' (lcP d)); [ | discriminate ].
    inversion H; subst. eexists; reflexivity.
Qed.

Definition pend (s : St) : list P3 := match s with T1 => [Pa] | _ => [] end.

Lemma dscan_oimg w : forall s v c I D,
  oimg s w = Some (c, I, D) -> dscan s w v = DOvf (rev_append D (pend s ++ v)).
Proof.
  induction w as [|x w IH]; intros s v c I D H; cbn [oimg] in H.
  - destruct s; try discriminate. inversion H; subst. reflexivity.
  - destruct x, s; cbn [dstep] in H; try discriminate;
      match type of H with context [oimg ?s' w] => destruct (oimg s' w) as [[[c' I'] D']|] eqn:E end;
      try discriminate;
      match type of H with context [aletter ?a ?b] => destruct (aletter a b) end;
      try discriminate; inversion H; subst; cbn [dscan];
      rewrite (IH _ _ _ _ _ E); reflexivity.
Qed.

(** The shifted pass with the carry made explicit. *)
Fixpoint ost (carry : Sym) (v : list P3) (acc : list L2) : option (Sym * list L2) :=
  match v with
  | [] => Some (carry, acc)
  | x :: v' => match aletter carry (lcP x) with
               | Some y => ost (rcP x) v' (y :: acc)
               | None => None
               end
  end.

Lemma ost_app v1 : forall c v2 acc,
  ost c (v1 ++ v2) acc = match ost c v1 acc with
                         | Some (c', acc') => ost c' v2 acc'
                         | None => None
                         end.
Proof.
  induction v1 as [|x v1 IH]; intros c v2 acc; cbn [ost app].
  - reflexivity.
  - destruct (aletter c (lcP x)); [ apply IH | reflexivity ].
Qed.

Lemma oscan_ost v : forall c acc,
  oscan c v acc = match ost c v acc with
                  | Some (0, acc') => Some acc'
                  | _ => None
                  end.
Proof.
  induction v as [|x v IH]; intros c acc; cbn [oscan ost].
  - destruct c; reflexivity.
  - destruct (aletter c (lcP x)); [ apply IH | reflexivity ].
Qed.

Lemma ost_oimg w : forall s c I D,
  oimg s w = Some (c, I, D) -> ost 0 (rev D) [La] = Some (c, I ++ [La]).
Proof.
  induction w as [|x w IH]; intros s c I D H; cbn [oimg] in H.
  - destruct s; try discriminate. inversion H; subst. reflexivity.
  - destruct (dstep s x) as [[d s']|]; [ | discriminate ].
    destruct (oimg s' w) as [[[c' I'] D']|] eqn:E; [ | discriminate ].
    destruct (aletter c' (lcP d)) as [y|] eqn:Ey; [ | discriminate ].
    inversion H; subst. cbn [rev].
    rewrite ost_app, (IH _ _ _ _ E). cbn [ost]. rewrite Ey. reflexivity.
Qed.

Lemma ovf_of_oscan v U : v <> [] -> oscan 0 v [La] = Some U -> ovf v = Next U.
Proof.
  destruct v as [|x v]; [ congruence | ]. intros _ H. unfold ovf.
  destruct (lcP x) eqn:E.
  - cbn [oscan] in H. rewrite E in H. discriminate.
  - rewrite H. reflexivity.
Qed.

Theorem sweep_ovf W I : oim T0 W = Some (1, I) -> sweep (Lb :: W) = Next (Lb :: Lb :: I ++ [La]).
Proof.
  intros H. destruct (oim_oimg _ _ _ _ H) as [D HD].
  unfold sweep. rewrite (dscan_oimg _ _ [Pb; Pc] _ _ _ HD). cbn [pend app].
  apply ovf_of_oscan.
  - rewrite rev_append_rev. destruct (rev D); discriminate.
  - rewrite rev_append_rev, oscan_ost, ost_app, (ost_oimg _ _ _ _ _ HD). reflexivity.
Qed.

(** ** Blocks *)

Fixpoint stt (s : St) (u : list L2) {struct u} : option St :=
  match u with
  | [] => Some s
  | x :: u' => match dstep s x with
               | None => None
               | Some (_, s') => stt s' u'
               end
  end.

(** Images of a block, given the carry coming from the letter to its left. *)
Fixpoint oblk (s : St) (u : list L2) (cin : Sym) {struct u} : option (Sym * list L2) :=
  match u with
  | [] => Some (cin, [])
  | x :: u' =>
    match dstep s x with
    | None => None
    | Some (d, s') =>
      match oblk s' u' cin with
      | None => None
      | Some (c', I') =>
        match aletter c' (lcP d) with
        | Some y => Some (rcP d, y :: I')
        | None => None
        end
      end
    end
  end.

Lemma oim_app u : forall s x so cx Ix c Iu,
  stt s u = Some so -> oim so x = Some (cx, Ix) -> oblk s u cx = Some (c, Iu) ->
  oim s (u ++ x) = Some (c, Iu ++ Ix).
Proof.
  induction u as [|a u IH]; intros s x so cx Ix c Iu Hs Hx Hu; cbn [stt oblk app oim] in *.
  - inversion Hs; inversion Hu; subst. exact Hx.
  - destruct (dstep s a) as [[d s']|]; [ | discriminate ].
    destruct (oblk s' u cx) as [[c' I']|] eqn:E; [ | discriminate ].
    rewrite (IH _ _ _ _ _ _ _ Hs Hx E).
    destruct (aletter c' (lcP d)); [ | discriminate ].
    inversion Hu; subst. reflexivity.
Qed.

Lemma stt_app u : forall s v, stt s (u ++ v) = match stt s u with Some so => stt so v | None => None end.
Proof.
  induction u as [|x u IH]; intros s v; cbn [stt app].
  - reflexivity.
  - destruct (dstep s x) as [[d s']|]; [ apply IH | reflexivity ].
Qed.

Lemma oblk_app u : forall s v so cin cv Iv c Iu,
  stt s u = Some so -> oblk so v cin = Some (cv, Iv) -> oblk s u cv = Some (c, Iu) ->
  oblk s (u ++ v) cin = Some (c, Iu ++ Iv).
Proof.
  induction u as [|a u IH]; intros s v so cin cv Iv c Iu Hs Hv Hu; cbn [stt oblk app] in *.
  - inversion Hs; inversion Hu; subst. exact Hv.
  - destruct (dstep s a) as [[d s']|]; [ | discriminate ].
    destruct (oblk s' u cv) as [[c' I']|] eqn:E; [ | discriminate ].
    rewrite (IH _ _ _ _ _ _ _ _ Hs Hv E).
    destruct (aletter c' (lcP d)); [ | discriminate ].
    inversion Hu; subst. reflexivity.
Qed.

Lemma stt_rep_a n : stt T0 (repeat La n) = Some T0.
Proof. induction n as [|n IH]; [ reflexivity | exact IH ]. Qed.

Lemma oblk_rep_a n : oblk T0 (repeat La n) 1 = Some (1, repeat Lb n).
Proof.
  induction n as [|n IH]; [ reflexivity | ].
  cbn [repeat oblk dstep]. rewrite IH. reflexivity.
Qed.

(** The level end for a record with block a^n: the new tail has [n] letters b. *)
Theorem sweep_ovf_UU n Z I :
  oim T1 Z = Some (0, I) ->
  sweep (UU n Z) = Next (UU 0 (repeat Lb n ++ La :: I ++ [La])).
Proof.
  intros H. unfold UU. cbn [repeat app].
  assert (H1 : oim T0 (Lb :: Z) = Some (1, La :: I)) by (cbn [oim dstep]; rewrite H; reflexivity).
  rewrite (sweep_ovf _ _ (oim_app _ _ _ _ _ _ _ _ (stt_rep_a n) H1 (oblk_rep_a n))).
  rewrite <- app_assoc. reflexivity.
Qed.

End Ovf356.

Module Tail356.

(** * 1RB0RB_0LC1RA_1RD1LC_1LA1LE_1LF0LD_---0LA: the tail b^(12q+r) is a periodic emitter (layer 1b)

    Generated file (the generator measures the 12-letter block facts and Coq re-checks
    every one of them by computation).  For r = 2, 6, 10 the suffix b^(12q+r) of the zone
    emits a fixed sequence of states; the gaps between emissions are multiplied by 4
    when q grows by 1.

    AI assistance: this proof, the scripts and the checks were produced with the help of Claude (Anthropic). *)

Import Sim356 Blocks356 Ovf356.
Import Lia PeanoNat.
Import Coq.Lists.List.
Import ListNotations.
Open Scope list_scope.
Open Scope nat_scope.

Definition B12 : list L2 := repeat Lb 12.

Ltac feed_chain := repeat (eapply FeedS; [ eassumption | reflexivity | ]); apply Feed0.
Ltac phase := eapply Feed_em; [ feed_chain | eassumption | reflexivity ].

(** ** r = 2: 3 transient emissions, period 2 *)

Module R2.

Fixpoint C0 (q : nat) : list L2 :=
  match q with
  | O => [Lb; Lb]
  | S q' => C0 q' ++ B12
  end
with C1 (q : nat) : list L2 :=
  match q with
  | O => [Lb; La]
  | S q' => C1 q' ++ [Lb; Lb; La; Lb; Lb; La; Lb; Lb; La; Lb; Lb; La]
  end
with C2 (q : nat) : list L2 :=
  match q with
  | O => [Lb; Lb]
  | S q' => C4 q' ++ [Lb; La; Lb; Lb; Lb; La; Lb; Lb; La; Lb; Lb; Lb]
  end
with C3 (q : nat) : list L2 :=
  match q with
  | O => [Lb; La]
  | S q' => C3 q' ++ [La; Lb; Lb; Lb; La; Lb; Lb; La; La; Lb; Lb; La]
  end
with C4 (q : nat) : list L2 :=
  match q with
  | O => [Lb; Lb]
  | S q' => C3 q' ++ [La; Lb; Lb; Lb; La; Lb; Lb; La; La; Lb; Lb; Lb]
  end.

Fixpoint G1 (q : nat) : nat :=
  match q with
  | O => 1
  | S q' => (0) + G1 q'
  end
with G2 (q : nat) : nat :=
  match q with
  | O => 1
  | S q' => (G2 q' + (G3 q' + (G4 q' + (G5 q' + (G4 q' + (G5 q' + (0))))))) + G4 q'
  end
with G3 (q : nat) : nat :=
  match q with
  | O => 1
  | S q' => (G5 q' + (G4 q' + (0))) + G5 q'
  end
with G4 (q : nat) : nat :=
  match q with
  | O => 1
  | S q' => (G4 q' + (G5 q' + (G4 q' + (0)))) + G5 q'
  end
with G5 (q : nat) : nat :=
  match q with
  | O => 1
  | S q' => (G4 q' + (G5 q' + (G4 q' + (0)))) + G5 q'
  end.

(** Emission 5 returns to the content after emission 3: from there on the emitter is periodic. *)
Theorem tail q :
  emf (G1 q) (C0 q) = Some (T0, C1 q) /\
  emf (G2 q) (C1 q) = Some (T2, C2 q) /\
  emf (G3 q) (C2 q) = Some (T0, C3 q) /\
  emf (G4 q) (C3 q) = Some (T2, C4 q) /\
  emf (G5 q) (C4 q) = Some (T0, C3 q).
Proof.
  induction q as [|q IH].
  - repeat split; vm_compute; reflexivity.
  - destruct IH as (H1 & H2 & H3 & H4 & H5).
    repeat split.
    + cbn [C0 C1 G1]. phase.
    + cbn [C1 C2 G2]. phase.
    + cbn [C2 C3 G3]. phase.
    + cbn [C3 C4 G4]. phase.
    + cbn [C3 C4 G5]. phase.
Qed.

Lemma C0_repeat q : C0 q = repeat Lb (12 * q + 2).
Proof.
  induction q as [|q IH]; [ reflexivity | ].
  cbn [C0]. rewrite IH. unfold B12. rewrite <- repeat_app. f_equal. lia.
Qed.

Lemma G1_S q : G1 (S q) = (0) + G1 q.
Proof. reflexivity. Qed.

Lemma G2_S q : G2 (S q) = (G2 q + (G3 q + (G4 q + (G5 q + (G4 q + (G5 q + (0))))))) + G4 q.
Proof. reflexivity. Qed.

Lemma G3_S q : G3 (S q) = (G5 q + (G4 q + (0))) + G5 q.
Proof. reflexivity. Qed.

Lemma G4_S q : G4 (S q) = (G4 q + (G5 q + (G4 q + (0)))) + G5 q.
Proof. reflexivity. Qed.

Lemma G5_S q : G5 (S q) = (G4 q + (G5 q + (G4 q + (0)))) + G5 q.
Proof. reflexivity. Qed.

(** Closed forms of the gaps, for q >= 1. *)
Lemma gaps q :
  3 * G1 (S q) = 0 * 4 ^ q + 3 /\
  3 * G2 (S q) + 2 = 23 * 4 ^ q /\
  3 * G3 (S q) = 9 * 4 ^ q + 0 /\
  3 * G4 (S q) = 12 * 4 ^ q + 0 /\
  3 * G5 (S q) = 12 * 4 ^ q + 0.
Proof.
  induction q as [|q IH]; [ cbn; lia | ].
  rewrite (G1_S (S q)), (G2_S (S q)), (G3_S (S q)), (G4_S (S q)), (G5_S (S q)).
  cbn [Nat.pow]. lia.
Qed.

End R2.

(** ** r = 6: 3 transient emissions, period 3 *)

Module R6.

Fixpoint C0 (q : nat) : list L2 :=
  match q with
  | O => [Lb; Lb; Lb; Lb; Lb; Lb]
  | S q' => C0 q' ++ B12
  end
with C1 (q : nat) : list L2 :=
  match q with
  | O => [Lb; La; Lb; Lb; La; Lb]
  | S q' => C1 q' ++ [Lb; La; Lb; Lb; La; Lb; Lb; La; Lb; Lb; La; Lb]
  end
with C2 (q : nat) : list L2 :=
  match q with
  | O => [Lb; La; La; Lb; Lb; La]
  | S q' => C4 q' ++ [La; Lb; Lb; La; La; Lb; Lb; La; La; Lb; Lb; La]
  end
with C3 (q : nat) : list L2 :=
  match q with
  | O => [Lb; Lb; La; Lb; Lb; La]
  | S q' => C4 q' ++ [La; Lb; Lb; La; La; Lb; Lb; Lb; La; Lb; Lb; La]
  end
with C4 (q : nat) : list L2 :=
  match q with
  | O => [Lb; La; La; Lb; Lb; Lb]
  | S q' => C4 q' ++ [La; Lb; Lb; La; La; Lb; Lb; La; La; Lb; Lb; Lb]
  end
with C5 (q : nat) : list L2 :=
  match q with
  | O => [Lb; Lb; Lb; La; Lb; Lb]
  | S q' => C4 q' ++ [La; Lb; Lb; La; La; Lb; Lb; Lb; Lb; La; Lb; Lb]
  end.

Fixpoint G1 (q : nat) : nat :=
  match q with
  | O => 1
  | S q' => (0) + G1 q'
  end
with G2 (q : nat) : nat :=
  match q with
  | O => 2
  | S q' => (G2 q' + (G3 q' + (G4 q' + (G5 q' + (G6 q' + (0)))))) + G4 q'
  end
with G3 (q : nat) : nat :=
  match q with
  | O => 3
  | S q' => (G5 q' + (G6 q' + (G4 q' + (G5 q' + (G6 q' + (G4 q' + (G5 q' + (G6 q' + (0))))))))) + G4 q'
  end
with G4 (q : nat) : nat :=
  match q with
  | O => 1
  | S q' => (G5 q' + (G6 q' + (0))) + G4 q'
  end
with G5 (q : nat) : nat :=
  match q with
  | O => 1
  | S q' => (G5 q' + (G6 q' + (0))) + G4 q'
  end
with G6 (q : nat) : nat :=
  match q with
  | O => 2
  | S q' => (G5 q' + (G6 q' + (G4 q' + (G5 q' + (G6 q' + (0)))))) + G4 q'
  end.

(** Emission 6 returns to the content after emission 3: from there on the emitter is periodic. *)
Theorem tail q :
  emf (G1 q) (C0 q) = Some (T1, C1 q) /\
  emf (G2 q) (C1 q) = Some (T0, C2 q) /\
  emf (G3 q) (C2 q) = Some (T0, C3 q) /\
  emf (G4 q) (C3 q) = Some (T2, C4 q) /\
  emf (G5 q) (C4 q) = Some (T2, C5 q) /\
  emf (G6 q) (C5 q) = Some (T0, C3 q).
Proof.
  induction q as [|q IH].
  - repeat split; vm_compute; reflexivity.
  - destruct IH as (H1 & H2 & H3 & H4 & H5 & H6).
    repeat split.
    + cbn [C0 C1 G1]. phase.
    + cbn [C1 C2 G2]. phase.
    + cbn [C2 C3 G3]. phase.
    + cbn [C3 C4 G4]. phase.
    + cbn [C4 C5 G5]. phase.
    + cbn [C3 C5 G6]. phase.
Qed.

Lemma C0_repeat q : C0 q = repeat Lb (12 * q + 6).
Proof.
  induction q as [|q IH]; [ reflexivity | ].
  cbn [C0]. rewrite IH. unfold B12. rewrite <- repeat_app. f_equal. lia.
Qed.

Lemma G1_S q : G1 (S q) = (0) + G1 q.
Proof. reflexivity. Qed.

Lemma G2_S q : G2 (S q) = (G2 q + (G3 q + (G4 q + (G5 q + (G6 q + (0)))))) + G4 q.
Proof. reflexivity. Qed.

Lemma G3_S q : G3 (S q) = (G5 q + (G6 q + (G4 q + (G5 q + (G6 q + (G4 q + (G5 q + (G6 q + (0))))))))) + G4 q.
Proof. reflexivity. Qed.

Lemma G4_S q : G4 (S q) = (G5 q + (G6 q + (0))) + G4 q.
Proof. reflexivity. Qed.

Lemma G5_S q : G5 (S q) = (G5 q + (G6 q + (0))) + G4 q.
Proof. reflexivity. Qed.

Lemma G6_S q : G6 (S q) = (G5 q + (G6 q + (G4 q + (G5 q + (G6 q + (0)))))) + G4 q.
Proof. reflexivity. Qed.

(** Closed forms of the gaps, for q >= 1. *)
Lemma gaps q :
  3 * G1 (S q) = 0 * 4 ^ q + 3 /\
  3 * G2 (S q) + 2 = 32 * 4 ^ q /\
  3 * G3 (S q) = 36 * 4 ^ q + 0 /\
  3 * G4 (S q) = 12 * 4 ^ q + 0 /\
  3 * G5 (S q) = 12 * 4 ^ q + 0 /\
  3 * G6 (S q) = 24 * 4 ^ q + 0.
Proof.
  induction q as [|q IH]; [ cbn; lia | ].
  rewrite (G1_S (S q)), (G2_S (S q)), (G3_S (S q)), (G4_S (S q)), (G5_S (S q)), (G6_S (S q)).
  cbn [Nat.pow]. lia.
Qed.

End R6.

(** ** r = 10: 4 transient emissions, period 1 *)

Module R10.

Fixpoint C0 (q : nat) : list L2 :=
