  rewrite (G1_S (S q)), (G2_S (S q)), (G3_S (S q)), (G4_S (S q)), (G5_S (S q)).
  cbn [Nat.pow]. lia.
Qed.

(** The periodic phase in detail: the content just before an emission, and its image at a level end. *)
Fixpoint H (q : nat) : nat :=
  match q with
  | O => 3
  | S q' => (G5 q' + (G5 q' + (G5 q' + (0)))) + H q'
  end.

Fixpoint Pre (q : nat) : list L2 :=
  match q with
  | O => [Lb; Lb; La; Lb; Lb; La; Lb; Lb; Lb; Lb]
  | S q' => Pre q' ++ [La; Lb; Lb; Lb; La; Lb; Lb; La; Lb; Lb; Lb; Lb]
  end.

Fixpoint Img (q : nat) : list L2 :=
