  | O => [Lb; Lb; Lb; La; Lb; Lb; Lb; La; Lb; Lb]
  | S q' => Img q' ++ [Lb; La; Lb; Lb; Lb; La; Lb; Lb; Lb; La; Lb; Lb]
  end.

Lemma G5_H q : G5 q = S (H q).
Proof.
  induction q as [|q IH]; [ reflexivity | ].
  cbn [G5 H]. rewrite IH at 4. lia.
Qed.

Lemma pre q : qf (H q) (C4 q) = Some (Pre q) /\ actp T1 (Pre q) = (C4 q, Some T0).
Proof.
  induction q as [|q [IH1 IH2]]; [ split; vm_compute; reflexivity | ].
  destruct (tail q) as (H1 & H2 & H3 & H4 & H5).
  split.
  - cbn [H C4 Pre].
    assert (HF : Feed (C4 q) [La; Lb; Lb; La; La; Lb; Lb; Lb; La; Lb; Lb; La] (G5 q + (G5 q + (G5 q + (0)))) (C4 q) [La; Lb; Lb; Lb; La; Lb; Lb; La; Lb; Lb; Lb; Lb]) by feed_chain.
    rewrite (qf_add _ (H q) _ _ (Feed_quiet _ _ _ _ _ HF)).
    apply qf_app. exact IH1.
  - cbn [C4 Pre]. rewrite actp_app, IH2. reflexivity.
Qed.

Lemma img q : stt T1 (Pre q) = Some T0 /\ oblk T1 (Pre q) 1%sym = Some (0%sym, Img q).
Proof.
  induction q as [|q [IH1 IH2]]; [ split; vm_compute; reflexivity | ].
  split.
  - cbn [Pre]. rewrite stt_app, IH1. reflexivity.
  - cbn [Pre Img]. eapply oblk_app; [ exact IH1 | reflexivity | exact IH2 ].
Qed.

End R10.

