End Tail356.

Module Level356.

(** * 1RB0RB_0LC1RA_1RD1LC_1LA1LE_1LF0LD_---0LA: a level is its q = 0 instance, slowed down (layer 1c)

    The zone of a level with tail b^(12q+r), q >= 1, is split into a delay line
    b^(12(q-1)+11) on the right and a reduced zone on the left.  The delay line passes
    one plain sweep to the reduced zone at sweeps 1, F, G, G+P, G+2P, ... (P = 4^q).

    AI assistance: this proof, the scripts and the checks were produced with the help of Claude (Anthropic). *)

Import Sim356 Blocks356 Ovf356 Tail356.
Import Lia PeanoNat.
Import Coq.Lists.List.
Import ListNotations.
Open Scope list_scope.
Open Scope nat_scope.

(** ** Sweeps of a zone, left-edge grows allowed *)

Definition zstep (Z : list L2) : option (list L2) :=
  match actp T1 Z with
  | (Z', None) => Some Z'
  | (Z', Some T0) => Some (Z' ++ [La])
  | _ => None
  end.

Fixpoint zrun (j : nat) (Z : list L2) : option (list L2) :=
  match j with
  | O => Some Z
  | S j' => match zstep Z with Some Z1 => zrun j' Z1 | None => None end
  end.

Lemma sweep_zstep n Z Z' : zstep Z = Some Z' -> sweep (UU n Z) = Next (UU (S n) Z').
Proof.
  unfold zstep. destruct (actp T1 Z) as [Z1 [[]|]] eqn:E; intros H; inversion H; subst.
  - apply sweep_grow. exact E.
  - apply sweep_quiet. exact E.
Qed.

Lemma run_zrun j : forall n Z Z', zrun j Z = Some Z' -> run j (UU n Z) = Next (UU (j + n) Z').
Proof.
  induction j as [|j IH]; intros n Z Z' H; cbn [zrun run] in *.
  - inversion H. reflexivity.
  - destruct (zstep Z) as [Z1|] eqn:E; [ | discriminate ].
    rewrite (sweep_zstep _ _ _ E), (IH _ _ _ H), Nat.add_succ_r. reflexivity.
Qed.

Lemma zrun_add j1 : forall j2 Z Z1, zrun j1 Z = Some Z1 -> zrun (j1 + j2) Z = zrun j2 Z1.
Proof.
  induction j1 as [|j1 IH]; intros j2 Z Z1 H; cbn [zrun Nat.add] in *.
  - inversion H. reflexivity.
  - destruct (zstep Z); [ apply IH; exact H | discriminate ].
Qed.

Lemma zrun_qf m : forall Z Z', qf m Z = Some Z' -> zrun m Z = Some Z'.
Proof.
  induction m as [|m IH]; intros Z Z' H; cbn [qf zrun] in *.
  - exact H.
  - unfold zstep. destruct (actp T1 Z) as [Z1 [s|]]; [ discriminate | ]. apply IH. exact H.
Qed.

Lemma run_add m1 : forall m2 U U1, run m1 U = Next U1 -> run (m1 + m2) U = run m2 U1.
Proof.
  induction m1 as [|m1 IH]; intros m2 U U1 H; cbn [run Nat.add] in *.
  - inversion H. reflexivity.
  - destruct (sweep U); try discriminate. apply IH. exact H.
Qed.

(** ** An emitter of T0 to the right of a reduced record *)

Lemma zstep_cascade Dp D' Z0 Z0' :
  actp T1 Dp = (D', Some T0) -> zstep Z0 = Some Z0' ->
  zstep (Dp ++ Lb :: Z0) = Some (D' ++ Lb :: Z0').
Proof.
  unfold zstep. intros H. rewrite actp_app, H. cbn [actp].
  destruct (actp T1 Z0) as [Z1 [[]|]]; intros H1; inversion H1; subst.
  - rewrite <- app_assoc. reflexivity.
  - reflexivity.
Qed.

Lemma zrun_emit m D D' Z0 Z0' :
  emf m D = Some (T0, D') -> zstep Z0 = Some Z0' ->
  zrun m (D ++ Lb :: Z0) = Some (D' ++ Lb :: Z0').
Proof.
  destruct m as [|m]; [ discriminate | ]. cbn [emf].
  destruct (qf m D) as [Dp|] eqn:E; [ | discriminate ].
  unfold em1. destruct (actp T1 Dp) as [u [s|]] eqn:E1; [ | discriminate ].
  intros H Hz. inversion H; subst.
  rewrite <- Nat.add_1_r.
  rewrite (zrun_add _ 1 _ _ (zrun_qf _ _ _ (qf_app _ _ _ (Lb :: Z0) E))).
  cbn [zrun]. rewrite (zstep_cascade _ _ _ _ E1 Hz). reflexivity.
Qed.

Lemma zrun_periodic g P : emf g P = Some (T0, P) ->
  forall j Z0 Z1, zrun j Z0 = Some Z1 -> zrun (j * g) (P ++ Lb :: Z0) = Some (P ++ Lb :: Z1).
Proof.
  intros HP. induction j as [|j IH]; intros Z0 Z1 H; cbn [zrun Nat.mul] in *.
  - inversion H. reflexivity.
  - destruct (zstep Z0) as [Za|] eqn:E; [ | discriminate ].
    rewrite (zrun_add _ _ _ _ (zrun_emit _ _ _ _ _ HP E)). apply IH. exact H.
Qed.

(** ** The level theorems.  [q] is the index of the delay line b^(12q+11);
       the level's tail is b^(12(q+1)+r). *)

Definition TT (q j : nat) : nat := R11.G1 q + (R11.G2 q + (R11.G3 q + j * R11.G4 q)).

Theorem level_quiet q j Z0 Z3 Z1 :
  zrun 3 Z0 = Some Z3 -> zrun j Z3 = Some Z1 ->
  zrun (TT q j) (R11.C0 q ++ Lb :: Z0) = Some (R11.C3 q ++ Lb :: Z1).
Proof.
  intros H3 Hj. destruct (R11.tail q) as (H1 & H2 & H3' & H4).
  cbn [zrun] in H3.
  destruct (zstep Z0) as [Za|] eqn:Ea; [ | discriminate ].
  destruct (zstep Za) as [Zb|] eqn:Eb; [ | discriminate ].
  destruct (zstep Zb) as [Zc|] eqn:Ec; [ | discriminate ].
  inversion H3; subst. unfold TT.
  rewrite (zrun_add _ _ _ _ (zrun_emit _ _ _ _ _ H1 Ea)).
  rewrite (zrun_add _ _ _ _ (zrun_emit _ _ _ _ _ H2 Eb)).
  rewrite (zrun_add _ _ _ _ (zrun_emit _ _ _ _ _ H3' Ec)).
  apply (zrun_periodic _ _ H4). exact Hj.
Qed.

Lemma level_pre q j Z0 Z3 Z1 :
  zrun 3 Z0 = Some Z3 -> zrun j Z3 = Some Z1 ->
  run (TT q j + R11.H q) (UU 0 (R11.C0 q ++ Lb :: Z0))
  = Next (UU (TT q j + R11.H q) (R11.Pre q ++ Lb :: Z1)).
Proof.
  intros H3 Hj. destruct (R11.pre q) as [P1 _].
  rewrite (run_zrun _ 0 _ (R11.Pre q ++ Lb :: Z1)).
  - rewrite Nat.add_0_r. reflexivity.
  - rewrite (zrun_add _ _ _ _ (level_quiet q j _ _ _ H3 Hj)).
    apply zrun_qf. apply qf_app. exact P1.
Qed.

Theorem level_end q j Z0 Z3 Z1 I :
  zrun 3 Z0 = Some Z3 -> zrun j Z3 = Some Z1 -> oim T0 (Lb :: Z1) = Some (1%sym, I) ->
  run (S (TT q j + R11.H q)) (UU 0 (R11.C0 q ++ Lb :: Z0))
  = Next (UU 0 (repeat Lb (TT q j + R11.H q) ++ La :: (R11.Img q ++ I) ++ [La])).
Proof.
  intros H3 Hj HI. destruct (R11.img q) as [I1 I2].
  rewrite <- Nat.add_1_r. rewrite (run_add _ 1 _ _ (level_pre q j _ _ _ H3 Hj)).
  cbn [run]. rewrite (sweep_ovf_UU _ _ (R11.Img q ++ I)); [ reflexivity | ].
  eapply oim_app; eassumption.
Qed.

Theorem level_halt q j Z0 Z3 Z1 Z' :
  zrun 3 Z0 = Some Z3 -> zrun j Z3 = Some Z1 -> actp T1 Z1 = (Z', Some T1) ->
  run (S (TT q j + R11.H q)) (UU 0 (R11.C0 q ++ Lb :: Z0)) = Halt.
Proof.
  intros H3 Hj HZ. destruct (R11.pre q) as [_ P2].
  rewrite <- Nat.add_1_r. rewrite (run_add _ 1 _ _ (level_pre q j _ _ _ H3 Hj)).
  cbn [run]. rewrite (sweep_halt _ _ (R11.C3 q ++ Lb :: Z')); [ reflexivity | ].
  rewrite actp_app, P2. cbn [actp]. rewrite HZ. reflexivity.
Qed.

(** The new tail length k' = TT q j + H q, for a delay line of index q + 1
    (level tail b^(12(q+2)+r)):  3 k' + 2 = (3 j + 11) 4^(q+2). *)
Lemma kform q j : 3 * (TT (S q) j + R11.H (S q)) + 2 = (3 * j + 11) * 4 ^ (q + 2).
Proof.
  unfold TT. pose proof (R11.gaps q) as (E1 & E2 & E3 & E4).
  pose proof (R11.G4_H (S q)) as E5.
  replace (q + 2) with (S (S q)) by lia. cbn [Nat.pow].
  remember (4 ^ q) as p eqn:Hp. clear Hp.
  remember (R11.G4 (S q)) as g4 eqn:Hg. clear Hg.
  assert (E6 : 3 * (j * g4) = j * (48 * p)) by nia.
  lia.
Qed.

End Level356.

Module Level1_356.

