Lemma start1 : U_B518 = UU 0 (R11.C0 42 ++ Lb :: Z0_1).
Proof. vm_compute. reflexivity. Qed.

Lemma red1_3 : zrun 3 Z0_1 = Some Z3_1.
Proof. vm_compute. reflexivity. Qed.

Lemma red1_j : zrun 1 Z3_1 = Some Z1_1.
Proof. vm_compute. reflexivity. Qed.

