(** Tail length and zone of level 2. *)
Definition K2 : nat := TT 42 1 + R11.H 42.
Definition S2 : list L2 := La :: (R11.Img 42 ++ I_1) ++ [La].

Lemma K2_form : 3 * K2 + 2 = 14 * 4 ^ 43.
