Module Sym356.

(** * 1RB0RB_0LC1RA_1RD1LC_1LA1LE_1LF0LD_---0LA: zones with symbolic run counts (layer 2a)

    A zone is written as a list of items: literal letters, or a unit repeated n times
    with n any natural number (possibly a variable).  The sweep, the level-end image and
    the halting test are evaluated on this representation; each evaluator is proved
    sound once.  A run whose count is a variable is crossed by a "front": a periodic
    source to the right of the run sends the same states every p sweeps, and each batch
    rewrites exactly one unit of the run (lemma [sfront]).

    AI assistance: this proof, the scripts and the checks were produced with the help of Claude (Anthropic). *)

Import Sim356 Blocks356 Ovf356 Tail356 Level356.
Import Lia PeanoNat.
Import Coq.Lists.List.
Import ListNotations.
Open Scope list_scope.
Open Scope nat_scope.

(** ** Words with runs *)

Fixpoint rep (u : list L2) (n : nat) : list L2 :=
  match n with
  | O => []
  | S n' => u ++ rep u n'
  end.

Lemma rep_snoc u n : rep u n ++ u = rep u (S n).
Proof.
  induction n as [|n IH]; cbn [rep].
  - rewrite app_nil_r. reflexivity.
  - rewrite <- app_assoc, IH. reflexivity.
Qed.

Inductive item := Lit (w : list L2) | Run (u : list L2) (n : nat).

Fixpoint den (W : list item) : list L2 :=
  match W with
  | [] => []
  | Lit w :: W' => w ++ den W'
  | Run u n :: W' => rep u n ++ den W'
  end.

Lemma den_app A B : den (A ++ B) = den A ++ den B.
Proof.
  induction A as [|[w|u n] A IH]; cbn [den app]; [ reflexivity | | ]; rewrite IH, app_assoc; reflexivity.
Qed.

Definition St_eqb (s t : St) : bool :=
  match s, t with
  | T0, T0 | T1, T1 | T2, T2 => true
  | _, _ => false
  end.

Lemma St_eqb_eq s t : St_eqb s t = true -> s = t.
Proof. destruct s, t; cbn; congruence. Qed.

Definition Sym_eqb (a b : Sym) : bool :=
  match a, b with
  | 0%sym, 0%sym | 1%sym, 1%sym => true
  | _, _ => false
  end.

Lemma Sym_eqb_eq a b : Sym_eqb a b = true -> a = b.
Proof. destruct a, b; cbn; congruence. Qed.

(** ** One scan *)

Lemma actp_rep u u' s : actp s u = (u', Some s) -> forall n, actp s (rep u n) = (rep u' n, Some s).
Proof.
  intros H. induction n as [|n IH]; cbn [rep].
  - reflexivity.
  - rewrite actp_app, H, IH. reflexivity.
Qed.

(** [f] is fuel; a run is passed in one step when the state leaves a unit as it entered
    it, and loses one unit (made literal) otherwise. *)
Fixpoint sactp (f : nat) (s : St) (W : list item) {struct f} : option (list item * option St) :=
  match f with
  | O => None
  | S f' =>
    match W with
    | [] => Some ([], Some s)
    | Lit w :: W' =>
      match actp s w with
      | (w', Some s') =>
        match sactp f' s' W' with
        | Some (W'', o) => Some (Lit w' :: W'', o)
        | None => None
        end
      | (w', None) => Some (Lit w' :: W', None)
      end
    | Run u n :: W' =>
      match actp s u with
      | (u', Some s') =>
        if St_eqb s s' then
          match sactp f' s W' with
          | Some (W'', o) => Some (Run u' n :: W'', o)
          | None => None
          end
        else
          match n with
          | O => sactp f' s W'
          | S n' =>
            match sactp f' s' (Run u n' :: W') with
            | Some (W'', o) => Some (Lit u' :: W'', o)
            | None => None
            end
          end
      | (u', None) =>
        match n with
        | O => sactp f' s W'
        | S n' => Some (Lit u' :: Run u n' :: W', None)
        end
      end
    end
  end.

Lemma sactp_sound f : forall s W W' o, sactp f s W = Some (W', o) -> actp s (den W) = (den W', o).
Proof.
  induction f as [|f IH]; intros s W W' o H; [ discriminate | ].
  destruct W as [|[w|u n] W]; cbn [sactp] in H.
  - inversion H; subst. reflexivity.
  - cbn [den]. rewrite actp_app. destruct (actp s w) as [w' [s'|]].
    + destruct (sactp f s' W) as [[W'' o']|] eqn:E; [ | discriminate ].
      inversion H; subst. rewrite (IH _ _ _ _ E). reflexivity.
    + inversion H; subst. reflexivity.
  - destruct (actp s u) as [u' [s'|]] eqn:E.
    + destruct (St_eqb s s') eqn:Eq.
      * apply St_eqb_eq in Eq. subst s'.
        destruct (sactp f s W) as [[W'' o']|] eqn:E2; [ | discriminate ].
        inversion H; subst. cbn [den].
        rewrite actp_app, (actp_rep _ _ _ E n), (IH _ _ _ _ E2). reflexivity.
      * destruct n as [|n'].
        -- cbn [den rep app]. apply IH. exact H.
        -- destruct (sactp f s' (Run u n' :: W)) as [[W'' o']|] eqn:E2; [ | discriminate ].
           inversion H; subst. apply IH in E2. cbn [den rep] in *.
           rewrite <- app_assoc, actp_app, E, E2. reflexivity.
    + destruct n as [|n'].
      * cbn [den rep app]. apply IH. exact H.
      * inversion H; subst. cbn [den rep].
        rewrite <- app_assoc, actp_app, E. reflexivity.
Qed.

(** ** Sweeps of a zone *)

Definition szstep (f : nat) (W : list item) : option (list item) :=
  match sactp f T1 W with
  | Some (W', None) => Some W'
  | Some (W', Some T0) => Some (W' ++ [Lit [La]])
  | _ => None
  end.

Fixpoint szrun (f M : nat) (W : list item) : option (list item) :=
  match M with
  | O => Some W
  | S M' => match szstep f W with Some W1 => szrun f M' W1 | None => None end
  end.

Lemma szstep_sound f W W' : szstep f W = Some W' -> zstep (den W) = Some (den W').
Proof.
  unfold szstep, zstep. intros H.
  destruct (sactp f T1 W) as [[W1 [[]|]]|] eqn:E; try discriminate;
    apply sactp_sound in E; rewrite E; inversion H; subst.
  - rewrite den_app. cbn [den]. rewrite app_nil_r. reflexivity.
  - reflexivity.
Qed.

Lemma szrun_sound f M : forall W W', szrun f M W = Some W' -> zrun M (den W) = Some (den W').
Proof.
  induction M as [|M IH]; intros W W' H; cbn [szrun zrun] in *.
  - inversion H. reflexivity.
  - destruct (szstep f W) as [W1|] eqn:E; [ | discriminate ].
    rewrite (szstep_sound _ _ _ E). apply IH. exact H.
Qed.

(** The form used by the generated files: the result of the evaluation only has to
    denote the same word as the stated one. *)
Lemma szrun_eq f M W W1 W' :
  szrun f M W = Some W1 -> den W1 = den W' -> zrun M (den W) = Some (den W').
Proof. intros H E. rewrite <- E. apply szrun_sound with f. exact H. Qed.

(** ** Emitted states *)

Definition ocons (o : option St) (l : list St) : list St :=
  match o with Some s => s :: l | None => l end.

Fixpoint thru (l : list St) (v : list L2) : list L2 * list St :=
  match l with
  | [] => (v, [])
  | s :: l' => let (v1, o) := actp s v in let (v', t) := thru l' v1 in (v', ocons o t)
  end.

Fixpoint srun (M : nat) (u : list L2) : list L2 * list St :=
  match M with
  | O => (u, [])
  | S M' => let (u1, o) := actp T1 u in let (u', l) := srun M' u1 in (u', ocons o l)
  end.

Lemma thru_nil l : thru l [] = ([], l).
Proof. induction l as [|s l IH]; cbn [thru actp]; [ | rewrite IH ]; reflexivity. Qed.

Lemma thru_app l : forall v w,
  thru l (v ++ w) = let (v', t) := thru l v in let (w', r) := thru t w in (v' ++ w', r).
Proof.
  induction l as [|s l IH]; intros v w; cbn [thru].
  - reflexivity.
  - rewrite actp_app. destruct (actp s v) as [v1 [t|]].
    + destruct (actp t w) as [w1 o] eqn:E. rewrite IH.
      destruct (thru l v1) as [v' t']. cbn [ocons thru]. rewrite E.
      destruct (thru t' w1) as [w' r]. reflexivity.
    + rewrite IH. destruct (thru l v1) as [v' t']. cbn [ocons].
      destruct (thru t' w) as [w' r]. reflexivity.
Qed.

Lemma srun_app M : forall u v,
  srun M (u ++ v) = let (u', l) := srun M u in let (v', t) := thru l v in (u' ++ v', t).
Proof.
  induction M as [|M IH]; intros u v; cbn [srun].
  - reflexivity.
  - rewrite actp_app. destruct (actp T1 u) as [u1 [t|]].
    + destruct (actp t v) as [v1 o] eqn:E. rewrite IH.
      destruct (srun M u1) as [u' l]. cbn [ocons thru]. rewrite E.
      destruct (thru l v1) as [v' t']. reflexivity.
    + rewrite IH. destruct (srun M u1) as [u' l]. cbn [ocons].
      destruct (thru l v) as [v' t']. reflexivity.
Qed.

Lemma srun_add a : forall b u,
  srun (a + b) u = let (u1, l1) := srun a u in let (u2, l2) := srun b u1 in (u2, l1 ++ l2).
Proof.
  induction a as [|a IH]; intros b u; cbn [Nat.add srun].
  - destruct (srun b u). reflexivity.
  - destruct (actp T1 u) as [u0 o]. rewrite IH.
    destruct (srun a u0) as [u1 l1]. destruct (srun b u1) as [u2 l2]. destruct o; reflexivity.
Qed.

Lemma thru_rep l V : thru l V = (V, l) -> forall c, thru l (rep V c) = (rep V c, l).
Proof.
  intros H. induction c as [|c IH]; cbn [rep].
  - apply thru_nil.
  - rewrite thru_app, H, IH. reflexivity.
Qed.

Lemma srun_zrun M : forall Z Z', srun M Z = (Z', []) -> zrun M Z = Some Z'.
Proof.
  induction M as [|M IH]; intros Z Z' H; cbn [srun zrun] in *.
  - inversion H. reflexivity.
  - unfold zstep. destruct (actp T1 Z) as [Z1 o]. destruct (srun M Z1) as [Z2 l] eqn:E.
    destruct o as [t|]; cbn [ocons] in H; [ discriminate | ].
    inversion H; subst. apply IH. exact E.
Qed.

(** ** The front *)

(** [R] is a periodic source: every [p] sweeps it sends the states [l] and is restored.
    The states pass each converted unit [V] unchanged, and one batch turns [F ++ U]
    (front, then the next unit) into [V ++ F]. *)
Lemma front_gen p R l F U V x :
  srun p R = (R, l) -> thru l (F ++ U) = (V ++ F, []) -> thru l V = (V, l) ->
  forall j c, srun (p * j) (R ++ rep V c ++ F ++ rep U j ++ x) = (R ++ rep V (c + j) ++ F ++ x, []).
Proof.
  intros HR HF HV. induction j as [|j IH]; intros c.
  - rewrite Nat.mul_0_r, Nat.add_0_r. reflexivity.
  - assert (E : srun p (R ++ rep V c ++ F ++ rep U (S j) ++ x)
                = (R ++ rep V (S c) ++ F ++ rep U j ++ x, [])).
    { rewrite <- (rep_snoc V c). change (rep U (S j)) with (U ++ rep U j).
      rewrite srun_app, HR. cbv beta iota.
      rewrite thru_app, (thru_rep _ _ HV c). cbv beta iota.
      replace (F ++ (U ++ rep U j) ++ x) with ((F ++ U) ++ rep U j ++ x)
        by (rewrite <- !app_assoc; reflexivity).
      rewrite thru_app, HF. cbv beta iota. cbn [thru].
      rewrite <- !app_assoc. reflexivity. }
    rewrite Nat.mul_succ_r, Nat.add_comm, srun_add, E. cbv beta iota. rewrite (IH (S c)).
    cbn [app]. rewrite Nat.add_succ_r. reflexivity.
Qed.

Fixpoint ssrun (f M : nat) (W : list item) : option (list item * list St) :=
  match M with
  | O => Some (W, [])
  | S M' =>
    match sactp f T1 W with
    | Some (W1, o) =>
      match ssrun f M' W1 with
      | Some (W', l) => Some (W', ocons o l)
      | None => None
      end
    | None => None
    end
  end.

Lemma ssrun_sound f M : forall W W' l, ssrun f M W = Some (W', l) -> srun M (den W) = (den W', l).
Proof.
  induction M as [|M IH]; intros W W' l H; cbn [ssrun srun] in *.
  - inversion H. reflexivity.
  - destruct (sactp f T1 W) as [[W1 o]|] eqn:E; [ | discriminate ].
    destruct (ssrun f M W1) as [[W2 l2]|] eqn:E2; [ | discriminate ].
    inversion H; subst. rewrite (sactp_sound _ _ _ _ _ E), (IH _ _ _ E2). reflexivity.
Qed.

Theorem sfront f p Rs R1 l F U V j rest :
  ssrun f p Rs = Some (R1, l) -> den R1 = den Rs ->
  thru l (F ++ U) = (V ++ F, []) -> thru l V = (V, l) ->
  zrun (p * j) (den (Rs ++ Lit F :: Run U j :: rest))
  = Some (den (Rs ++ Run V j :: Lit F :: rest)).
Proof.
  intros H1 H2 H3 H4. apply ssrun_sound in H1. rewrite H2 in H1.
  apply srun_zrun. rewrite !den_app. cbn [den].
  pose proof (front_gen p (den Rs) l F U V (den rest) H1 H3 H4 j 0) as E.
  cbn [rep app Nat.add] in E. exact E.
Qed.

(** ** The level-end image *)

Lemma stt_rep s u : stt s u = Some s -> forall n, stt s (rep u n) = Some s.
Proof.
  intros H. induction n as [|n IH]; cbn [rep]; [ reflexivity | ].
  rewrite stt_app, H. exact IH.
Qed.

Lemma oblk_rep s u c u' : stt s u = Some s -> oblk s u c = Some (c, u') ->
  forall n, oblk s (rep u n) c = Some (c, rep u' n).
Proof.
  intros Hs Hu. induction n as [|n IH]; cbn [rep]; [ reflexivity | ].
  eapply oblk_app; eassumption.
Qed.

Fixpoint soim (f : nat) (s : St) (W : list item) {struct f} : option (Sym * list item) :=
  match f with
  | O => None
  | S f' =>
    match W with
    | [] => match s with T2 => Some (0%sym, []) | _ => None end
    | Lit w :: W' =>
      match stt s w with
      | None => None
      | Some so =>
        match soim f' so W' with
        | None => None
        | Some (cx, Ix) =>
          match oblk s w cx with
          | None => None
          | Some (c, Iw) => Some (c, Lit Iw :: Ix)
          end
        end
      end
    | Run u n :: W' =>
      match stt s u with
      | None => None
      | Some so =>
        if St_eqb s so then
          match soim f' s W' with
          | None => None
          | Some (cx, Ix) =>
            match oblk s u cx with
            | None => None
            | Some (c1, uA) =>
              if Sym_eqb c1 cx then Some (cx, Run uA n :: Ix)
              else
                match n with
                | O => Some (cx, Ix)
                | S n' =>
                  match oblk s u c1 with
                  | None => None
                  | Some (c2, uB) =>
                    if Sym_eqb c2 c1 then Some (c1, Run uB n' :: Lit uA :: Ix) else None
                  end
                end
            end
          end
        else
          match n with
          | O => soim f' s W'
          | S n' => soim f' s (Lit u :: Run u n' :: W')
          end
      end
    end
  end.

Lemma soim_sound f : forall s W c I, soim f s W = Some (c, I) -> oim s (den W) = Some (c, den I).
Proof.
  induction f as [|f IH]; intros s W c I H; [ discriminate | ].
  destruct W as [|[w|u n] W]; cbn [soim] in H.
  - destruct s; inversion H; subst; reflexivity.
  - destruct (stt s w) as [so|] eqn:Es; [ | discriminate ].
    destruct (soim f so W) as [[cx Ix]|] eqn:E; [ | discriminate ].
    destruct (oblk s w cx) as [[c' Iw]|] eqn:Eo; [ | discriminate ].
    inversion H; subst. cbn [den]. eapply oim_app; [ exact Es | exact (IH _ _ _ _ E) | exact Eo ].
  - destruct (stt s u) as [so|] eqn:Es; [ | discriminate ].
    destruct (St_eqb s so) eqn:Eq.
    + apply St_eqb_eq in Eq. subst so.
      destruct (soim f s W) as [[cx Ix]|] eqn:E; [ | discriminate ].
      apply IH in E.
      destruct (oblk s u cx) as [[c1 uA]|] eqn:Eo; [ | discriminate ].
      destruct (Sym_eqb c1 cx) eqn:Ec.
      * apply Sym_eqb_eq in Ec. subst c1. inversion H; subst. cbn [den].
        eapply oim_app; [ exact (stt_rep _ _ Es n) | exact E | exact (oblk_rep _ _ _ _ Es Eo n) ].
      * destruct n as [|n'].
        -- inversion H; subst. cbn [den rep app]. exact E.
        -- destruct (oblk s u c1) as [[c2 uB]|] eqn:Eo2; [ | discriminate ].
           destruct (Sym_eqb c2 c1) eqn:Ec2; [ | discriminate ].
           apply Sym_eqb_eq in Ec2. subst c2. inversion H; subst.
           cbn [den]. rewrite <- (rep_snoc u n').
           replace (rep uB n' ++ uA ++ den Ix) with ((rep uB n' ++ uA) ++ den Ix)
             by (rewrite <- app_assoc; reflexivity).
           eapply oim_app; [ | exact E | ].
           ++ rewrite stt_app, (stt_rep _ _ Es n'). exact Es.
           ++ eapply oblk_app; [ exact (stt_rep _ _ Es n') | exact Eo | exact (oblk_rep _ _ _ _ Es Eo2 n') ].
    + destruct n as [|n'].
      * cbn [den rep app]. apply IH. exact H.
      * apply IH in H. cbn [den rep] in *. rewrite <- app_assoc. exact H.
Qed.

Lemma soim_end f W1 I :
  soim f T0 (Lit [Lb] :: W1) = Some (1%sym, I) -> oim T0 (Lb :: den W1) = Some (1%sym, den I).
Proof. intros H. apply soim_sound in H. exact H. Qed.

Lemma soim_end_eq f W1 I1 I :
  soim f T0 (Lit [Lb] :: W1) = Some (1%sym, I1) -> den I1 = den I ->
  oim T0 (Lb :: den W1) = Some (1%sym, den I).
Proof. intros H E. rewrite <- E. exact (soim_end _ _ _ H). Qed.

(** ** The zone at the start of a level *)

Definition img0 : list L2 := [Lb; Lb; Lb; La; Lb; Lb; Lb; La; Lb; Lb; Lb].
Definition imglit : list L2 := [La; Lb; Lb; Lb; La; Lb; Lb; Lb; La; Lb; Lb; Lb].

Lemma Img_rep q : R11.Img q = img0 ++ rep imglit q.
Proof.
  induction q as [|q IH].
  - reflexivity.
  - cbn [R11.Img]. rewrite IH, <- app_assoc. fold imglit. rewrite rep_snoc. reflexivity.
Qed.

(** A tail of [K = 12 q + 12 + r] letters b, the zone left by the previous level
    (delay line of index [qp], image [I]): delay line b^(12q+11), the block's b, and the
    reduced zone b^r a Img(qp) I a. *)
Lemma zone_form K q r qp I : K = 12 * q + 12 + r ->
  repeat Lb K ++ La :: (R11.Img qp ++ den I) ++ [La]
  = R11.C0 q ++ Lb :: den (Lit (repeat Lb r ++ La :: img0) :: Run imglit qp :: I ++ [Lit [La]]).
Proof.
  intros ->. rewrite R11.C0_repeat, Img_rep.
  replace (12 * q + 12 + r) with ((12 * q + 11) + S r) by lia.
  rewrite repeat_app. cbn [repeat den]. rewrite den_app. cbn [den].
  repeat (progress (rewrite <- ?app_assoc; cbn [app])). reflexivity.
Qed.

(** ** Tactics for the generated level files

    Every word is computed by the evaluator; the kernel re-runs each computation at Qed. *)

(** A literal number of sweeps, last piece: [zrun M (den W) = Some (den W')]. *)
Ltac lit_last f :=
  lazymatch goal with
  | |- zrun ?M (den ?W) = Some (den ?W') =>
    let r := eval vm_compute in (szrun f M W) in
    lazymatch r with
    | Some ?W1 =>
      apply (szrun_eq f M W W1 W');
      [ vm_cast_no_check (@eq_refl (option (list item)) (Some W1)) | vm_compute; reflexivity ]
    end
  end.

(** A literal number of sweeps followed by more: [zrun (M + rst) (den W) = _]. *)
Ltac lit_step f :=
  lazymatch goal with
  | |- zrun (?M + ?rst) (den ?W) = _ =>
    let r := eval vm_compute in (szrun f M W) in
    lazymatch r with
    | Some ?W1 =>
      let H := fresh "H" in
      assert (H : szrun f M W = Some W1)
        by (vm_cast_no_check (@eq_refl (option (list item)) (Some W1)));
      rewrite (zrun_add M rst (den W) (den W1) (szrun_sound f M W W1 H)); clear H
    end
  end.

(** A front crossing a run: [zrun (p * j + rst) (den W) = _] with [W] denoting
    [Rs ++ Lit F :: Run U j :: rest]. *)
Ltac front_step f p Rs F U V rest :=
  lazymatch goal with
  | |- zrun (p * ?j + ?rst) (den ?W) = _ =>
    replace (den W) with (den (Rs ++ Lit F :: Run U j :: rest)) by (vm_compute; reflexivity);
    let r := eval vm_compute in (ssrun f p Rs) in
    lazymatch r with
    | Some (?R1, ?l) =>
      let H := fresh "H" in
      assert (H : zrun (p * j) (den (Rs ++ Lit F :: Run U j :: rest))
                  = Some (den (Rs ++ Run V j :: Lit F :: rest)))
        by (apply (sfront f p Rs R1 l F U V j rest);
            [ vm_cast_no_check (@eq_refl (option (list item * list St)) (Some (R1, l)))
            | vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity ]);
      rewrite (zrun_add (p * j) rst _ _ H); clear H
    end
  end.

(** The level-end image: [oim T0 (Lb :: den W1) = Some (1, den I)]. *)
Ltac image_tac f :=
  lazymatch goal with
  | |- oim T0 (Lb :: den ?W1) = Some (_, den ?I) =>
    let r := eval vm_compute in (soim f T0 (Lit [Lb] :: W1)) in
    lazymatch r with
    | Some (_, ?I1) =>
      apply (soim_end_eq f W1 I1 I);
      [ vm_cast_no_check (@eq_refl (option (Sym * list item)) (Some (1%sym, I1))) | vm_compute; reflexivity ]
    end
  end.

(** The halting sweep: [exists Z', actp T1 (den W1) = (Z', Some T1)]. *)
Ltac halt_tac f :=
  lazymatch goal with
  | |- exists Z', actp T1 (den ?W1) = (Z', Some T1) =>
    let r := eval vm_compute in (sactp f T1 W1) in
    lazymatch r with
    | Some (?W', Some T1) =>
      exists (den W'); apply (sactp_sound f T1 W1 W' (Some T1));
      vm_cast_no_check (@eq_refl (option (list item * option St)) (Some (W', Some T1)))
    end
  end.

End Sym356.

Module Step356.

(** * 1RB0RB_0LC1RA_1RD1LC_1LA1LE_1LF0LD_---0LA: one level, as a step of the chain (layer 2c)

    A level whose tail is b^(12q+12+r) and whose reduced instance (tail b^r) ends in an
    overflow after 3 + j quiet sweeps leaves a tail of K letters with
    3 K + 2 = (3 j + 11) 4^(q+1); if the reduced instance halts, the machine halts.

    AI assistance: this proof, the scripts and the checks were produced with the help of Claude (Anthropic). *)

Import Sim356 Blocks356 Ovf356 Tail356 Level356 Sym356.
Import Lia PeanoNat.
Import Coq.Lists.List.
Import ListNotations.
Open Scope list_scope.
Open Scope nat_scope.

Theorem level_step q j Z0 Z3 Z1 I :
  1 <= q -> zrun 3 Z0 = Some Z3 -> zrun j Z3 = Some Z1 ->
  oim T0 (Lb :: Z1) = Some (1%sym, I) ->
  c0 -->* rec (UU 0 (R11.C0 q ++ Lb :: Z0)) ->
  exists K, 3 * K + 2 = (3 * j + 11) * 4 ^ (q + 1) /\
            c0 -->* rec (UU 0 (repeat Lb K ++ La :: (R11.Img q ++ I) ++ [La])).
Proof.
  intros Hq H3 Hj HI Hc. destruct q as [|q0]; [ lia | ].
  exists (TT (S q0) j + R11.H (S q0)). split.
  - rewrite (kform q0 j). replace (S q0 + 1) with (q0 + 2) by lia. reflexivity.
  - eapply run_reach; [ exact Hc | exact (level_end (S q0) j Z0 Z3 Z1 I H3 Hj HI) ].
Qed.

Theorem level_halts q j Z0 Z3 Z1 :
  zrun 3 Z0 = Some Z3 -> zrun j Z3 = Some Z1 ->
  (exists Z', actp T1 Z1 = (Z', Some T1)) ->
  c0 -->* rec (UU 0 (R11.C0 q ++ Lb :: Z0)) -> halts tm c0.
Proof.
  intros H3 Hj [Z' HZ] Hc.
  eapply run_halts; [ exact Hc | exact (level_halt q j Z0 Z3 Z1 Z' H3 Hj HZ) ].
Qed.

Lemma pow4_lin q : 1 <= q -> 8 * (q + 1) <= 4 ^ (q + 1).
Proof.
  induction 1 as [|q Hq IH].
  - cbn. lia.
  - replace (S q + 1) with (S (q + 1)) by lia. rewrite Nat.pow_succ_r'. lia.
Qed.

(** The delay-line index does not decrease from one level to the next. *)
Lemma q_grows q j K q' r :
  4 <= q -> 3 * K + 2 = (3 * j + 11) * 4 ^ (q + 1) -> K = 12 * q' + 12 + r -> r < 12 -> q <= q'.
Proof.
  intros Hq HK HS Hr. pose proof (pow4_lin q ltac:(lia)) as P.
  remember (4 ^ (q + 1)) as p eqn:Ep. clear Ep.
  assert (11 * p <= (3 * j + 11) * p) by nia. lia.
Qed.

End Step356.

