    The tail lengths K of the levels are towers of 4.  They are never computed:
    this file carries their residues modulo 4 * 3^e from one level to the next.

    If the tail of a level is K = 12 q + 12 + r and the level ends with
    3 K' + 2 = A * 4^(q + d), then K' modulo 4 * 3^e is fixed by q modulo 3^e
    and A modulo 3^(e+1), because 4^(3^e) = 1 modulo 3^(e+1).  One level costs
    one power of 3.

    All moduli and residues are binary integers ([Z]); the tower quantities stay
    abstract natural numbers and enter only through [Z.of_nat].

    AI assistance: this proof, the scripts and the checks were produced with the help of Claude (Anthropic). *)

Import ZArith Lia PeanoNat Znumtheory Zpow_facts.
Open Scope Z_scope.

(** ** Powers of 3 *)

Definition p3 (e : nat) : Z := 3 ^ Z.of_nat e.

Lemma p3_S e : p3 (S e) = 3 * p3 e.
Proof. unfold p3. rewrite Nat2Z.inj_succ, Z.pow_succ_r by lia. reflexivity. Qed.

Lemma p3_pos e : 0 < p3 e.
Proof. unfold p3. apply Z.pow_pos_nonneg; lia. Qed.

Lemma p3_add d e : p3 (d + e) = p3 d * p3 e.
Proof. unfold p3. rewrite Nat2Z.inj_add, Z.pow_add_r by lia. reflexivity. Qed.

(** ** The order of 4 modulo powers of 3 *)

Lemma pow4_p3 e : exists t, 4 ^ p3 e = 1 + p3 (S e) * t.
Proof.
  induction e as [|e [t IH]].
  - exists 1. reflexivity.
  - pose proof (p3_pos e) as Hp. rewrite p3_S in IH.
    exists (t + 3 * p3 e * t ^ 2 + 3 * p3 e ^ 2 * t ^ 3).
    rewrite (p3_S (S e)), !(p3_S e).
    assert (E : 4 ^ (3 * p3 e) = (4 ^ p3 e) ^ 3)
      by (rewrite (Z.mul_comm 3), Z.pow_mul_r by lia; reflexivity).
    rewrite E, IH. ring.
Qed.

Lemma pow4_period e a t :
  0 <= a -> 0 <= t -> 4 ^ (a + p3 e * t) mod p3 (S e) = 4 ^ a mod p3 (S e).
Proof.
  intros Ha Ht. pose proof (p3_pos e) as Hp. pose proof (p3_pos (S e)) as Hp'.
  rewrite Z.pow_add_r by nia. rewrite Z.pow_mul_r by lia.
  destruct (pow4_p3 e) as [s Hs]. rewrite Hs.
  rewrite Zmult_mod. rewrite (Zpower_mod (1 + p3 (S e) * s)) by exact Hp'.
  assert (E : (1 + p3 (S e) * s) mod p3 (S e) = 1 mod p3 (S e))
    by (rewrite (Z.mul_comm (p3 (S e)) s); apply Z_mod_plus_full).
  rewrite E.
  rewrite <- Zpower_mod by exact Hp'. rewrite Z.pow_1_l by exact Ht.
  rewrite <- Zmult_mod. rewrite Z.mul_1_r. reflexivity.
Qed.

(** Fast modular exponentiation: the standard library's [Zpow_mod] (square and multiply). *)
Definition modpow (b x m : Z) : Z := Zpow_mod b x m.

Lemma modpow_spec b x m : 0 < m -> modpow b x m = b ^ x mod m.
Proof. intros H. unfold modpow. apply Zpow_mod_correct. lia. Qed.

(** ** From natural numbers to integers *)

Lemma kform_Z (K A x : nat) :
  (3 * K + 2 = A * 4 ^ x)%nat -> 3 * Z.of_nat K + 2 = Z.of_nat A * 4 ^ Z.of_nat x.
Proof.
  intros H. apply (f_equal Z.of_nat) in H.
  rewrite Nat2Z.inj_add, !Nat2Z.inj_mul, Nat2Z.inj_pow in H. exact H.
Qed.

(** The exact value, for a level whose data are still small. *)
Lemma K_exact (K A x : nat) :
  (3 * K + 2 = A * 4 ^ x)%nat -> Z.of_nat K = (Z.of_nat A * 4 ^ Z.of_nat x - 2) / 3.
Proof.
  intros H. apply kform_Z in H. rewrite <- H.
  replace (3 * Z.of_nat K + 2 - 2) with (Z.of_nat K * 3) by ring.
  rewrite Z.div_mul by lia. reflexivity.
Qed.

Lemma q_exact (K q r : nat) :
  (K = 12 * q + 12 + r)%nat -> Z.of_nat q = (Z.of_nat K - 12 - Z.of_nat r) / 12.
Proof.
  intros H. subst K. rewrite !Nat2Z.inj_add, Nat2Z.inj_mul.
  change (Z.of_nat 12) with 12.
  replace (12 * Z.of_nat q + 12 + Z.of_nat r - 12 - Z.of_nat r) with (Z.of_nat q * 12) by ring.
  rewrite Z.div_mul by lia. reflexivity.
Qed.

Lemma res_of_eq (x : nat) (v m c : Z) : Z.of_nat x = v -> v mod m = c -> Z.of_nat x mod m = c.
Proof. intros -> H. exact H. Qed.

Lemma K_ge (K A x : nat) : (3 * K + 2 = A * 4 ^ x)%nat -> (10 <= A)%nat -> (1 <= x)%nat -> (12 <= K)%nat.
Proof.
  intros H HA Hx. destruct x as [|x]; [ lia | ].
  rewrite Nat.pow_succ_r' in H.
  assert (1 <= 4 ^ x)%nat by (apply Nat.neq_0_lt_0, Nat.pow_nonzero; lia).
  nia.
Qed.

(** ** One level: the residue of the new tail *)

(** [Kres e d cq cA] is K' modulo 4 * 3^e when 3 K' + 2 = A * 4^(q + d),
    q = cq modulo 3^e and A = cA modulo 3^(e+1)  (d >= 1). *)
Definition Kres (e d : nat) (cq cA : Z) : Z :=
  let m := p3 e in
  ((4 * ((cA * modpow 4 (cq + Z.of_nat d - 1) (3 * m)) mod (3 * m)) - 2) mod (12 * m)) / 3.

Theorem K_step (e d : nat) (K A q : nat) (cq cA cK : Z) :
  (3 * K + 2 = A * 4 ^ (q + d))%nat ->
  (1 <= d)%nat ->
  Z.of_nat q mod p3 e = cq ->
  Z.of_nat A mod p3 (S e) = cA ->
  Kres e d cq cA = cK ->
  Z.of_nat K mod (4 * p3 e) = cK.
Proof.
  intros H Hd Hq HA HK. apply kform_Z in H.
  pose proof (p3_pos e) as Hp. rewrite p3_S in HA.
  set (m := p3 e) in *. set (K' := Z.of_nat K) in *. set (A' := Z.of_nat A) in *.
  rewrite Nat2Z.inj_add in H.
  set (q' := Z.of_nat q) in *. set (d' := Z.of_nat d) in *.
  assert (Hd' : 1 <= d') by (unfold d'; lia).
  assert (Hq' : 0 <= q') by (unfold q'; lia).
  (* the residue of 4^(q+d-1) modulo 3m *)
  assert (Hc : 0 <= cq) by (rewrite <- Hq; apply Z.mod_pos_bound; exact Hp).
  assert (E1 : 4 ^ (q' + d' - 1) mod (3 * m) = modpow 4 (cq + d' - 1) (3 * m)).
  { rewrite modpow_spec by lia.
    replace (q' + d' - 1) with ((cq + d' - 1) + m * (q' / m))
      by (rewrite <- Hq; pose proof (Z.div_mod q' m); lia).
    unfold m. rewrite <- p3_S. apply pow4_period; [ lia | ].
    apply Z.div_pos; [ exact Hq' | exact Hp ]. }
  (* W = A * 4^(q+d-1) *)
  set (W := A' * 4 ^ (q' + d' - 1)).
  assert (HW : 3 * K' + 2 = 4 * W).
  { assert (EP : 4 ^ (q' + d') = 4 * 4 ^ (q' + d' - 1))
      by (rewrite <- Z.pow_succ_r by lia; f_equal; lia).
    rewrite H, EP. unfold W. ring. }
  assert (E2 : W mod (3 * m) = (cA * modpow 4 (cq + d' - 1) (3 * m)) mod (3 * m)).
  { unfold W. rewrite Zmult_mod, HA, E1. reflexivity. }
  assert (E3 : (3 * K') mod (12 * m) = (4 * (W mod (3 * m)) - 2) mod (12 * m)).
  { replace (3 * K') with (4 * W - 2) by lia.
    rewrite <- Zmult_mod_distr_l. replace (4 * (3 * m)) with (12 * m) by ring.
    rewrite Zminus_mod_idemp_l. reflexivity. }
  replace (12 * m) with (3 * (4 * m)) in E3 at 1 by ring.
  rewrite Zmult_mod_distr_l in E3.
  rewrite <- HK. unfold Kres. cbv zeta. fold m. fold d'. rewrite <- E2, <- E3.
  rewrite (Z.mul_comm 3 (K' mod (4 * m))), Z.div_mul by lia. reflexivity.
Qed.

(** The multiplier A = 3 j + 11 gains one power of 3 over j. *)
Lemma A_res (e j : nat) (cj cA : Z) :
  Z.of_nat j mod p3 e = cj ->
  (3 * cj + 11) mod p3 (S e) = cA ->
  Z.of_nat (3 * j + 11) mod p3 (S e) = cA.
Proof.
  intros Hj HA. rewrite Nat2Z.inj_add, Nat2Z.inj_mul.
  change (Z.of_nat 3) with 3. change (Z.of_nat 11) with 11.
  rewrite <- HA, <- Hj, p3_S.
  rewrite <- Zmult_mod_distr_l. rewrite Zplus_mod_idemp_l. reflexivity.
Qed.

(** [K_step] for the form in which the level theorem states the new tail. *)
Theorem K_step_j (e d : nat) (K j q : nat) (cq cj cK : Z) :
  (3 * K + 2 = (3 * j + 11) * 4 ^ (q + d))%nat ->
  (1 <= d)%nat ->
  Z.of_nat q mod p3 e = cq ->
  Z.of_nat j mod p3 e = cj ->
  Kres e d cq ((3 * cj + 11) mod p3 (S e)) = cK ->
  Z.of_nat K mod (4 * p3 e) = cK.
Proof.
  intros H Hd Hq Hj HK.
  eapply K_step; [ exact H | exact Hd | exact Hq | | exact HK ].
  eapply A_res; [ exact Hj | reflexivity ].
Qed.

(** ** Splitting the tail: K = 12 q + 12 + r *)

Lemma K_mod12 (e K : nat) (cK : Z) :
  Z.of_nat K mod (4 * p3 (S e)) = cK -> Z.of_nat K mod 12 = cK mod 12.
Proof.
  intros H. rewrite <- H. pose proof (p3_pos e) as Hp.
  apply Zmod_div_mod; [ lia | rewrite p3_S; lia | ].
  exists (p3 e). rewrite p3_S. ring.
Qed.

Theorem K_split (e K r : nat) (cK : Z) :
  Z.of_nat K mod (4 * p3 (S e)) = cK ->
  cK mod 12 = Z.of_nat r ->
  (12 <= K)%nat ->
  (K = 12 * (K / 12 - 1) + 12 + r)%nat.
Proof.
  intros H Hr HK. apply K_mod12 in H. rewrite Hr in H.
  assert (E : (K mod 12 = r)%nat).
  { apply Nat2Z.inj. rewrite Nat2Z.inj_mod. exact H. }
  pose proof (Nat.div_mod_eq K 12) as HD. rewrite E in HD.
  remember (K / 12)%nat as dd eqn:Hdd. clear Hdd H Hr.
  assert (r < 12)%nat by (rewrite <- E; apply Nat.mod_upper_bound; lia).
  lia.
Qed.

Theorem q_step (e K q r : nat) (cK cq : Z) :
  (K = 12 * q + 12 + r)%nat ->
  (r < 12)%nat ->
  Z.of_nat K mod (4 * p3 (S e)) = cK ->
  ((cK - 12 - Z.of_nat r) / 12) mod p3 e = cq ->
  Z.of_nat q mod p3 e = cq.
Proof.
  intros HK Hr H Hc. pose proof (p3_pos e) as Hp.
  apply (f_equal Z.of_nat) in HK. rewrite !Nat2Z.inj_add, Nat2Z.inj_mul in HK.
  change (Z.of_nat 12) with 12 in HK.
  set (K' := Z.of_nat K) in *. set (q' := Z.of_nat q) in *. set (r' := Z.of_nat r) in *.
  assert (Hr' : 0 <= r' < 12) by (unfold r'; lia).
  rewrite p3_S in H. replace (4 * (3 * p3 e)) with (12 * p3 e) in H by ring.
  rewrite Z.rem_mul_r in H by lia.
  assert (Em : K' mod 12 = r').
  { symmetry. apply (Z.mod_unique_pos K' 12 (q' + 1) r'); lia. }
  assert (Ed : K' / 12 = q' + 1).
  { symmetry. apply (Z.div_unique_pos K' 12 (q' + 1) r'); lia. }
  rewrite Em, Ed in H.
  rewrite <- Hc, <- H.
  replace (r' + 12 * ((q' + 1) mod p3 e) - 12 - r') with (((q' + 1) mod p3 e - 1) * 12) by ring.
  rewrite Z.div_mul by lia.
  rewrite Zminus_mod_idemp_l. f_equal. ring.
Qed.

(** ** Lowering the precision *)

Lemma res_divide (m n x c c' : Z) :
  0 < n -> 0 < m -> (n | m) -> x mod m = c -> c mod n = c' -> x mod n = c'.
Proof.
  intros Hn Hm Hd H Hc. rewrite <- Hc, <- H. apply Zmod_div_mod; assumption.
Qed.

Lemma res_down (d e : nat) (x c c' : Z) :
  x mod p3 (d + e) = c -> c mod p3 e = c' -> x mod p3 e = c'.
Proof.
  intros H Hc. eapply res_divide; [ apply p3_pos | apply (p3_pos (d + e)) | | exact H | exact Hc ].
  exists (p3 d). apply p3_add.
Qed.

Lemma res_down1 (e : nat) (x c c' : Z) :
  x mod p3 (S e) = c -> c mod p3 e = c' -> x mod p3 e = c'.
Proof. apply (res_down 1 e). Qed.

Lemma res_down4 (e : nat) (x c c' : Z) :
  x mod (4 * p3 e) = c -> c mod p3 e = c' -> x mod p3 e = c'.
Proof.
  intros H Hc. pose proof (p3_pos e) as Hp.
  eapply res_divide; [ exact Hp | | | exact H | exact Hc ]; [ lia | ].
  exists 4. reflexivity.
Qed.

(** ** Residues of affine expressions *)

Lemma res_add (m : Z) (x y : nat) (cx cy : Z) :
  Z.of_nat x mod m = cx -> Z.of_nat y mod m = cy ->
  Z.of_nat (x + y) mod m = (cx + cy) mod m.
Proof. intros <- <-. rewrite Nat2Z.inj_add. apply Zplus_mod. Qed.

Lemma res_mul (m : Z) (x y : nat) (cx cy : Z) :
  Z.of_nat x mod m = cx -> Z.of_nat y mod m = cy ->
  Z.of_nat (x * y) mod m = (cx * cy) mod m.
Proof. intros <- <-. rewrite Nat2Z.inj_mul. apply Zmult_mod. Qed.

Lemma res_lit (m : Z) (k : nat) : Z.of_nat k mod m = Z.of_nat k mod m.
Proof. reflexivity. Qed.

(** A count given as [c = k + y]: the residue of [y] from that of [c]. *)
Lemma res_shift (m : Z) (c k y : nat) (cc cy : Z) :
  (c = k + y)%nat -> Z.of_nat c mod m = cc -> (cc - Z.of_nat k) mod m = cy ->
  Z.of_nat y mod m = cy.
Proof.
  intros E H Hc. rewrite <- Hc, <- H. rewrite Zminus_mod_idemp_l. f_equal. lia.
Qed.

(** A run count 3 q + c gains one power of 3 over q. *)
Lemma res_3q (e q k : nat) (cq c : Z) :
  Z.of_nat q mod p3 e = cq ->
  (3 * cq + Z.of_nat k) mod p3 (S e) = c ->
  Z.of_nat (k + 3 * q) mod p3 (S e) = c.
Proof.
  intros Hq Hc. rewrite Nat2Z.inj_add, Nat2Z.inj_mul. change (Z.of_nat 3) with 3.
  rewrite <- Hc, <- Hq, p3_S.
  rewrite <- Zmult_mod_distr_l. rewrite Zplus_mod_idemp_l. f_equal. ring.
Qed.

Ltac is_nat_lit t :=
  lazymatch t with
  | O => idtac
  | S ?n => is_nat_lit n
  | _ => fail "not a literal"
  end.

(** [res_build] proves [Z.of_nat t mod m = ?c] for [t] built with [+] and [*] from
    literals and from atoms [a] that have a hypothesis [Z.of_nat a mod m = ca]
    (same modulus, found by syntactic equality: nothing is unfolded). *)
Ltac res_build :=
  lazymatch goal with
  | |- Z.of_nat (?x + ?y) mod _ = _ => eapply res_add; [ res_build | res_build ]
  | |- Z.of_nat (?x * ?y) mod _ = _ => eapply res_mul; [ res_build | res_build ]
  | |- Z.of_nat ?k mod _ = _ =>
      first [ is_nat_lit k; apply res_lit
            | match goal with H : Z.of_nat ?a mod _ = _ |- _ => constr_eq a k; exact H end
            | fail 1 "no residue hypothesis for" k ]
  end.

(** [res_solve] proves [Z.of_nat t mod m = c] for a closed [c]. *)
Ltac res_solve := etransitivity; [ res_build | vm_compute; reflexivity ].

(** ** A worked example with the data of level 1 and level 2 *)

End Resid356.

Module Reach356.

(** * 1RB0RB_0LC1RA_1RD1LC_1LA1LE_1LF0LD_---0LA: the chain of levels and the halting theorem (layer 3)

    Generated file.  [ReachN] says that the machine reaches the start of level N: tail
    b^(12q+12+r), zone in the form of the level file, with the residues of q and of the
    run counts modulo a power of 3.  Each step applies the level theorem, computes the
    residue of the new tail and rewrites the new zone in the form of the next level.
    Level 25 halts.

    AI assistance: this proof, the scripts and the checks were produced with the help of Claude (Anthropic). *)

Import Sim356 Blocks356 Ovf356 Tail356 Level356 Sym356 Step356 Resid356 Test356 Level1_356.
Import ZArith Lia PeanoNat.
Import Coq.Lists.List.
Import ListNotations.
Open Scope list_scope.
Open Scope nat_scope.

Definition Reach2 : Prop :=
  exists q : nat,
    c0 -->* rec (UU 0 (R11.C0 q ++ Lb :: den (Lev2_356.W0 )))
    /\ 1000 <= q
    /\ (Z.of_nat q mod p3 24 = 97639870189)%Z.

Lemma reach2 : Reach2.
Proof.
  assert (H2 : exists K, 3 * K + 2 = 14 * 4 ^ 43 /\ c0 -->* rec (UU 0 (repeat Lb K ++ S2)))
    by (exists K2; split; [ exact K2_form | exact level1 ]).
  destruct H2 as (K & HK & Hc).
  assert (VK : Z.of_nat K = 361065844791569246845577898%Z) by (rewrite (K_exact _ _ _ HK); vm_compute; reflexivity).
  assert (RK : (Z.of_nat K mod (4 * p3 25) = 1171678442286)%Z) by (eapply res_of_eq; [ exact VK | vm_compute; reflexivity ]).
  assert (GK : 12 <= K) by (eapply K_ge; [ exact HK | clear; lia | clear; lia ]).
  assert (SK : K = 12 * (K / 12 - 1) + 12 + 6)
    by (eapply (K_split 24); [ exact RK | vm_compute; reflexivity | exact GK ]).
  assert (Vq : Z.of_nat (K / 12 - 1) = 30088820399297437237131490%Z)
    by (rewrite (q_exact _ _ _ SK), VK; vm_compute; reflexivity).
  remember (K / 12 - 1) as q eqn:E0. clear E0.
  assert (Rq : (Z.of_nat q mod p3 24 = 97639870189)%Z) by (eapply res_of_eq; [ exact Vq | vm_compute; reflexivity ]).
  assert (Gq : 1000 <= q) by (clear - Vq; lia).
  unfold S2 in Hc. change I_1 with (den [Lit I_1]) in Hc.
  rewrite (zone_form K q 6 42 [Lit I_1] SK) in Hc.
  assert (EZ : den (Lit (repeat Lb 6 ++ La :: img0) :: Run imglit 42 :: [Lit I_1] ++ [Lit [La]]) = den Lev2_356.W0)
    by (vm_compute; reflexivity).
  rewrite EZ in Hc.
  exists q. exact (conj Hc (conj Gq Rq)).
Qed.

Definition Reach3 : Prop :=
  exists q xq : nat,
    c0 -->* rec (UU 0 (R11.C0 q ++ Lb :: den (Lev3_356.W0 xq)))
    /\ 1000 <= q
    /\ (Z.of_nat q mod p3 23 = 15938652886)%Z
    /\ (Z.of_nat xq mod p3 23 = 3496691360)%Z
    /\ 900 <= xq.

Lemma step2 : Reach2 -> Reach3.
Proof.
  unfold Reach2, Reach3.
  intros (q & Hc & Gq & Rq).
  destruct (level_step q (Lev2_356.J ) _ _ _ _ ltac:(clear - Gq; lia) (Lev2_356.first ) (Lev2_356.main ) (Lev2_356.image ) Hc)
    as (K & HK & Hc'). clear Hc.
  assert (RJ : (Z.of_nat (Lev2_356.J ) mod p3 24 = 4211)%Z) by (unfold Lev2_356.J; res_solve).
  assert (RK : (Z.of_nat K mod (4 * p3 24) = 191263834650)%Z)
    by (eapply K_step_j; [ exact HK | clear; lia | exact Rq | exact RJ | vm_compute; reflexivity ]).
  assert (GK : 12 <= K) by (eapply K_ge; [ exact HK | clear; lia | clear; lia ]).
  assert (SK : K = 12 * (K / 12 - 1) + 12 + 6)
    by (eapply (K_split 23); [ exact RK | vm_compute; reflexivity | exact GK ]).
  remember (K / 12 - 1) as q' eqn:E0. clear E0.
  assert (Rq' : (Z.of_nat q' mod p3 23 = 15938652886)%Z)
    by (eapply q_step; [ exact SK | clear; lia | exact RK | vm_compute; reflexivity ]).
  assert (Gq' : 1000 <= q')
    by (apply (Nat.le_trans _ q); [ exact Gq | eapply q_grows; [ | exact HK | exact SK | ]; clear - Gq; lia ]).
  rewrite (zone_form K q' 6 q (Lev2_356.Im ) SK) in Hc'.
  remember (q - 2) as b_xq eqn:E0. assert (Eq : q = 2 + b_xq) by (clear - E0 Gq; lia). clear E0.
  assert (Rb_xq : (Z.of_nat b_xq mod p3 23 = 3496691360)%Z)
    by (eapply res_shift; [ exact Eq | eapply res_down1; [ exact Rq | vm_compute; reflexivity ] | vm_compute; reflexivity ]).
  assert (Lb_xq : 900 <= b_xq) by (clear - Eq Gq; lia).
  assert (EZ : den (Lit (repeat Lb 6 ++ La :: img0) :: Run imglit q :: Lev2_356.Im  ++ [Lit [La]])
               = den (Lev3_356.W0 b_xq)).
  { rewrite Eq. vm_compute. reflexivity. }
  rewrite EZ in Hc'. clear EZ.
  exists q'. exists b_xq.
  exact (conj Hc' (conj Gq' (conj Rq' (conj Rb_xq Lb_xq)))).
Qed.

Lemma reach3 : Reach3.
Proof. exact (step2 reach2). Qed.

Definition Reach4 : Prop :=
  exists q xq x0 : nat,
    c0 -->* rec (UU 0 (R11.C0 q ++ Lb :: den (Lev4_356.W0 xq x0)))
    /\ 1000 <= q
    /\ (Z.of_nat q mod p3 22 = 21270722858)%Z
    /\ (Z.of_nat xq mod p3 22 = 15938652884)%Z
    /\ (Z.of_nat x0 mod p3 22 = 3496691358)%Z
    /\ 900 <= xq
    /\ 898 <= x0.

Lemma step3 : Reach3 -> Reach4.
Proof.
  unfold Reach3, Reach4.
  intros (q & a_xq & Hc & Gq & Rq & R_xq & L_xq).
  destruct (level_step q (Lev3_356.J a_xq) _ _ _ _ ltac:(clear - Gq; lia) (Lev3_356.first a_xq) (Lev3_356.main a_xq) (Lev3_356.image a_xq) Hc)
    as (K & HK & Hc'). clear Hc.
  assert (RJ : (Z.of_nat (Lev3_356.J a_xq) mod p3 23 = 53252838590)%Z) by (unfold Lev3_356.J; res_solve).
  assert (RK : (Z.of_nat K mod (4 * p3 23) = 255248674314)%Z)
    by (eapply K_step_j; [ exact HK | clear; lia | exact Rq | exact RJ | vm_compute; reflexivity ]).
  assert (GK : 12 <= K) by (eapply K_ge; [ exact HK | clear; lia | clear; lia ]).
  assert (SK : K = 12 * (K / 12 - 1) + 12 + 6)
    by (eapply (K_split 22); [ exact RK | vm_compute; reflexivity | exact GK ]).
  remember (K / 12 - 1) as q' eqn:E0. clear E0.
  assert (Rq' : (Z.of_nat q' mod p3 22 = 21270722858)%Z)
